(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"reading-comprehension-inference":{"title":"Inference","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-inference-q0001","version":3,"contentHash":"sha256:43996ac3b0443184dca160d3247124ebcb84bf2bbe0d101a84835610314b9a74","question":"Sara put on her boots, scarf, and coat. She grabbed her sled. What can you infer?","choices":["Sara is going to the beach.","Sara is going to play in the snow.","Sara is going to school.","Sara is going to bed."],"correct":1,"explanation":{"correct":"Answer: Sara is going to play in the snow. An inference is a conclusion based on evidence from the text. Boots, a scarf, a coat, and a sled are all items specifically used for cold, snowy weather.","incorrect":[{"choice":"Sara is going to the beach.","category":"ignores text evidence","reason":"Beach trips usually involve swimsuits and towels, not coats and sleds. These items do not fit the evidence provided in the sentence."},"",{"choice":"Sara is going to school.","category":"unsupported by clues","reason":"While students wear coats to school, carrying a sled is not typical school behavior. The mention of a sled is a strong clue pointing to play rather than school."},{"choice":"Sara is going to bed.","category":"conflicting evidence","reason":"You would wear pajamas to bed, not boots and outdoor winter gear. This choice contradicts the specific items Sara is putting on."}]},"studyAid":{"definition":"An inference is like reading between the lines; it uses what you already know plus clues from the story to guess what is happening.","example":"Text: The boy picked up an umbrella. Inference: It is raining or about to rain.","strategyClue":"Look at each object mentioned in the text and list where you would usually see that object. Choose the option that fits all the objects together at the same time.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":1,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0002","version":3,"contentHash":"sha256:e5c046688cbbdcebe1b619ebf8b1b018149001bd151b2c29a86cf3dea4d0172b","question":"Tom's teeth were chattering, and he rubbed his arms. What can you infer?","choices":["Tom is hot.","Tom is cold.","Tom is tired.","Tom is hungry."],"correct":1,"explanation":{"correct":"Answer: Tom is cold. When someone's teeth chatter and they rub their arms, it is a physical reaction to being in a cold environment, helping us infer the temperature.","incorrect":[{"choice":"Tom is hot.","category":"incorrect inference","reason":"Teeth chattering and rubbing arms are signs of a body trying to warm up, not symptoms of being hot."},"",{"choice":"Tom is tired.","category":"incorrect inference","reason":"While feeling tired might involve yawning or rubbing eyes, it does not typically cause teeth to chatter."},{"choice":"Tom is hungry.","category":"incorrect inference","reason":"Hunger usually causes a growling stomach, whereas chattering teeth is a specific response to low temperatures."}]},"studyAid":{"definition":"An inference is a logical guess you make by combining what you already know with clues provided in the text.","example":"Clue: The dark clouds gathered and the wind picked up. Inference: It is going to rain.","strategyClue":"Think about how your own body acts in different situations. What physical actions do you do when you are freezing, sleepy, or hungry?","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":2,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0003","version":3,"contentHash":"sha256:4bb10ced5732bb8c88f9d6c0082a8dd840deab3d2b861e5f97ee90a0a040f80d","question":"The ground was covered in crumbs, and the cookie jar was empty. What can you infer?","choices":["Someone baked cookies.","Someone ate the cookies.","The jar was broken.","The cookies were given away."],"correct":1,"explanation":{"correct":"Answer: Someone ate the cookies. An inference is a conclusion drawn from evidence. Since the jar is empty and there are crumbs nearby, the most logical reason for the missing cookies is that someone ate them.","incorrect":[{"choice":"Someone baked cookies.","category":"unsupported conclusion","reason":"While baking cookies would explain their existence, it does not explain why the jar is now empty or why there are crumbs scattered on the ground."},"",{"choice":"The jar was broken.","category":"not based on text","reason":"The sentence mentions an empty jar and crumbs, but it provides no evidence that the jar itself is damaged or shattered."},{"choice":"The cookies were given away.","category":"unlikely scenario","reason":"Giving away cookies would leave an empty jar, but it would not explain the presence of crumbs on the ground around the jar."}]},"studyAid":{"definition":"An inference is using clues from the text and what you already know to figure out something that isn't directly stated.","example":"Clue: She put on her raincoat. Inference: It is raining. Clue: The dog is wagging its tail. Inference: The dog is happy.","strategyClue":"Look at each answer choice and ask yourself: 'Does the text provide evidence to prove this happened?' Look for the one that best explains both the empty jar and the crumbs.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":3,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0004","version":3,"contentHash":"sha256:0c78232f9bb1d61ea2e4abfb6f87b10d42aaf40f6e7537978e70c9d315edc47c","question":"Maria looked at her watch, sighed, and tapped her foot. What can you infer?","choices":["Maria is relaxed.","Maria is bored.","Maria is waiting impatiently.","Maria is asleep."],"correct":2,"explanation":{"correct":"Answer: Maria is waiting impatiently. Looking at a watch and tapping a foot are classic body language cues that show someone is checking the time because they are in a hurry or eager for something to happen.","incorrect":[{"choice":"Maria is relaxed.","category":"mismatched body language","reason":"When someone is relaxed, they usually breathe slowly and keep their limbs still. Tapping a foot suggests restlessness rather than being calm."},{"choice":"Maria is bored.","category":"incorrect emotional context","reason":"While tapping a foot can sometimes happen when bored, checking a watch repeatedly combined with tapping usually points toward being in a rush, not just having nothing to do."},"",{"choice":"Maria is asleep.","category":"logical inconsistency","reason":"If Maria were asleep, she would not be looking at a watch or tapping her foot. These actions require being awake and alert."}]},"studyAid":{"definition":"An inference is a smart guess based on evidence from the text combined with what you already know about the world.","example":"If a character is shivering, you infer they are cold. If a character is crying, you infer they are sad.","strategyClue":"Visualize the character's actions as if you were watching a movie. Think about how those specific movements would make you feel if you were doing them, then choose the option that matches that energy.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":4,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0005","version":3,"contentHash":"sha256:124b87ccd548a41c38abd26e9dab6a6ee129f2d37c17067186101e1d99a40d31","question":"The classroom was silent. Everyone looked at the door. What can you infer?","choices":["Class is over.","Someone important entered.","It is lunchtime.","The students are sleeping."],"correct":1,"explanation":{"correct":"Answer: Someone important entered. In literature, when a silent room suddenly shifts focus to the door, it implies that someone of significance or authority has arrived.","incorrect":[{"choice":"Class is over.","category":"incorrect inferential leap","reason":"While class ending might cause students to look at the door, the intense silence described is more characteristic of a high-stakes arrival rather than the routine bustle of a bell ringing."},"",{"choice":"It is lunchtime.","category":"illogical situational inference","reason":"Lunchtime usually involves noise and movement rather than the hushed silence described. This choice does not fit the specific emotional tone of the scene."},{"choice":"The students are sleeping.","category":"contradictory evidence","reason":"The text says 'Everyone looked at the door,' which requires the students to be awake and observant, making it impossible for them to be sleeping."}]},"studyAid":{"definition":"An inference is a logical guess you make by combining what the author says with what you already know about the world.","example":"Text: The person held an umbrella and wore boots. Inference: It is raining outside.","strategyClue":"Look for \"clue words\" that set the mood (like 'silent'), then ask yourself, 'What real-life event usually makes people react in this specific way?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":5,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0006","version":3,"contentHash":"sha256:793036944d1fc6dffbbecc4cc8549868f97292808a95f7e2a664ecc6804feab4","question":"Jake's face turned red, and he clenched his fists. What can you infer?","choices":["Jake is happy.","Jake is angry.","Jake is sad.","Jake is scared."],"correct":1,"explanation":{"correct":"Answer: Jake is angry. Clenching fists and a face turning red are physical signs often associated with frustration or anger, helping us infer his emotional state.","incorrect":[{"choice":"Jake is happy.","category":"mismatched emotional state","reason":"People do not usually clench their fists or turn red when they are happy. These physical clues signal a negative emotion instead."},"",{"choice":"Jake is sad.","category":"conflicting physical cues","reason":"While red faces can happen during crying, clenching fists is more commonly a sign of tension or aggression rather than the sorrow associated with being sad."},{"choice":"Jake is scared.","category":"misinterpreted physical reaction","reason":"Scared people might shake or hide, but clenching fists is an active, aggressive reaction that points toward anger rather than fear."}]},"studyAid":{"definition":"An inference is using clues from the text and what you already know to figure out something the author didn't say directly.","example":"If the author writes 'He shivered and wrapped his coat tighter,' you can infer he is cold.","strategyClue":"Connect the physical actions described in the text to real-life situations where you have seen those same behaviors. What emotion usually causes someone to make those specific movements?","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":6,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0007","version":3,"contentHash":"sha256:b3ad0dc0898e77b0c669d33ba899ba9cc5ffc633ee34b74925e5df4ab107bb26","question":"The dog wagged its tail and jumped up and down when Max came home. What can you infer?","choices":["The dog is scared of Max.","The dog is happy to see Max.","The dog is hungry.","The dog is tired."],"correct":1,"explanation":{"correct":"Answer: The dog is happy to see Max. Wagging a tail and jumping up and down are common behaviors dogs show when they are excited and pleased to see their owners.","incorrect":[{"choice":"The dog is scared of Max.","category":"incorrect inference","reason":"When dogs are scared, they usually try to hide, tuck their tails, or growl. Jumping up and down shows excitement, not fear."},"",{"choice":"The dog is hungry.","category":"unsupported inference","reason":"While a dog might jump if it is hungry, 'wagging its tail' when someone comes home is most strongly associated with greeting a loved one, not just begging for food."},{"choice":"The dog is tired.","category":"contradictory inference","reason":"Jumping up and down takes a lot of energy. A tired dog would likely be lying down or moving slowly, not leaping up and down."}]},"studyAid":{"definition":"An inference is a logical guess based on what you already know and the clues provided in the text.","example":"If someone is shivering and wearing a coat, you can infer it is cold outside. If a child has a band-aid on their knee, you can infer they might have fallen.","strategyClue":"Look at the character's physical actions—wagging and jumping—and ask yourself, 'What human feeling matches these specific movements?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":7,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0008","version":3,"contentHash":"sha256:a8401eadabe15b87205de78fb9b52efa0463ee89f1066515ae0202a773b07536","question":"The shelves were empty, and people carried bags out of the store. What can you infer?","choices":["The store just opened.","There was a big sale.","The store is closed.","The store is restocking."],"correct":1,"explanation":{"correct":"Answer: There was a big sale. Inferences use evidence from the text to draw a logical conclusion. If shelves were empty and many people were leaving with bags, it implies that customers had recently purchased most of the items.","incorrect":[{"choice":"The store just opened.","category":"ignoring textual evidence","reason":"If the store had just opened, the shelves would likely be full, and people would be entering rather than carrying bags out."},"",{"choice":"The store is closed.","category":"contradicting text clues","reason":"The text says people are carrying bags 'out of the store,' which indicates the store is still serving customers and is not closed."},{"choice":"The store is restocking.","category":"unsupported assumption","reason":"While possible, this doesn't explain why people are leaving with bags. The act of customers leaving with items points more directly to a successful sale event."}]},"studyAid":{"definition":"An inference is an educated guess based on evidence from the text combined with what you already know about the world.","example":"Text: Smoke rises from the chimney. Inference: Someone is using the fireplace. Text: The boy wears a coat and scarf. Inference: It is cold outside.","strategyClue":"Ask yourself what the people are doing and look for clues about the store's status. Choose the option that best connects the empty shelves to the customers leaving the building.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":8,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0009","version":3,"contentHash":"sha256:57b7e1eb00d498637b51f3a4d4b0f1e746f4fbc55dbec578b6ba7e1e24f16930","question":"Lucy yawned, rubbed her eyes, and asked for a blanket. What can you infer?","choices":["Lucy is hungry.","Lucy is sleepy.","Lucy is excited.","Lucy is angry."],"correct":1,"explanation":{"correct":"Answer: Lucy is sleepy. Inferences are conclusions reached based on evidence; rubbing eyes and yawning are classic physical signs of being tired.","incorrect":[{"choice":"Lucy is hungry.","category":"mismatched evidence","reason":"Hunger is usually associated with a growling stomach or asking for food, not yawning or rubbing eyes."},"",{"choice":"Lucy is excited.","category":"inconsistent emotion","reason":"Excitement typically involves smiling, jumping, or wide eyes, which contradicts the tired actions of yawning and rubbing eyes."},{"choice":"Lucy is angry.","category":"mismatched behavior","reason":"Angry people might shout or frown, but yawning and rubbing eyes are behaviors linked to fatigue, not anger."}]},"studyAid":{"definition":"An inference is when you use clues from a story and your own knowledge to figure out something that the author didn't state directly.","example":"Clue: The ground is wet. Inference: It rained outside. Clue: He is wearing a swimsuit and carrying a towel. Inference: He is going swimming.","strategyClue":"Identify the physical actions in the sentence and ask yourself: 'In what situation would a person normally do these things?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":9,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0010","version":3,"contentHash":"sha256:a85a6ebcfe77075454e38cae331942f223564259b65569bcf63246b6c0dd1be9","question":"The car had a flat tire and smoke coming from the hood. What can you infer?","choices":["The car is brand new.","The car broke down.","The car is being washed.","The car is out of gas."],"correct":1,"explanation":{"correct":"Answer: The car broke down. An inference is a conclusion based on clues in the text; a flat tire and smoke are clear signs that a vehicle is experiencing a mechanical failure.","incorrect":[{"choice":"The car is brand new.","category":"contradictory evidence","reason":"Brand new cars typically do not have flat tires or smoke. This choice ignores the negative clues provided in the sentence."},"",{"choice":"The car is being washed.","category":"unsupported assumption","reason":"There is no mention of water, soap, or cleaning in the sentence. You cannot infer an activity that has no evidence in the text."},{"choice":"The car is out of gas.","category":"specific cause error","reason":"While the car is not working, 'out of gas' would not explain the flat tire or the smoke coming from the hood."}]},"studyAid":{"definition":"An inference is a smart guess made by combining the facts in the text with what you already know about how the world works.","example":"Clue: 'He grabbed his umbrella.' Inference: It is likely raining outside.","strategyClue":"Look at each clue in the sentence—the flat tire and the smoke—and ask yourself what kind of situation causes those specific problems to happen at the same time.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":10,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0011","version":3,"contentHash":"sha256:c861278218637cd5d567d9d4c0c2e9d5617c1f6072fa8a3f53732c1056cf83e1","question":"The child carried an umbrella and wore rain boots. What can you infer?","choices":["It is sunny.","It is raining or about to rain.","It is snowing.","It is windy."],"correct":1,"explanation":{"correct":"Answer: It is raining or about to rain. Since the child has an umbrella and rain boots, it is logical to infer that the weather involves precipitation, which matches the purpose of these items.","incorrect":[{"choice":"It is sunny.","category":"logic error","reason":"Umbrellas and rain boots are used to protect against water, not sunlight. This choice ignores the specific function of the items mentioned."},"",{"choice":"It is snowing.","category":"insufficient evidence","reason":"While it can snow in cold weather, rain boots and umbrellas are specifically designed for rain. Snow usually requires winter boots and a heavy coat."},{"choice":"It is windy.","category":"logic error","reason":"Wind does not require an umbrella or rain boots; in fact, umbrellas often break in high winds. The items clearly point toward rain."}]},"studyAid":{"definition":"An inference is a logical conclusion you reach by combining what you read in the text with what you already know from your own life experiences.","example":"Text: The boy grabbed a plate and fork. Inference: The boy is going to eat. Text: The girl put on a swimsuit. Inference: She is going to swim.","strategyClue":"Ask yourself, 'What are these objects usually used for?' Then, select the option that describes the environment where those objects would be most helpful.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":11,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0012","version":3,"contentHash":"sha256:098d9a8c4a2b2fe144bb3556c3f350c41ece5c254a4998ec6f4d029e68eb56d5","question":"Maya's hands were covered in paint, and there was a canvas on the table. What can you infer?","choices":["Maya was cooking.","Maya was painting.","Maya was gardening.","Maya was reading."],"correct":1,"explanation":{"correct":"Answer: Maya was painting. Since the paint was on Maya's hands and there was a canvas nearby, it is logical to conclude that she was the one using the paint to create art.","incorrect":[{"choice":"Maya was cooking.","category":"Incorrect situational logic","reason":"Cooking usually involves ingredients and kitchen tools, not paint and canvases. The presence of paint strongly points toward art, not food preparation."},"",{"choice":"Maya was gardening.","category":"Incorrect situational logic","reason":"Gardening happens outdoors with soil and plants. Finding paint and a canvas suggests an indoor activity involving art supplies."},{"choice":"Maya was reading.","category":"Incorrect situational logic","reason":"Reading requires a book and a quiet space. Paint on the hands would be messy and unusual for reading, whereas it is a standard part of painting."}]},"studyAid":{"definition":"An inference is a logical guess you make by combining the details in the text with what you already know from your own life experiences.","example":"Clue: The girl shivered and put on a coat. Inference: It is cold outside. Clue: The boy dropped his ice cream. Inference: The boy felt sad.","strategyClue":"Look at the specific objects mentioned in the sentence, like 'paint' and 'canvas', and ask yourself, 'What activity usually requires these items?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":12,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0013","version":3,"contentHash":"sha256:66e872bab0d8c1de1552f5773b290bfe605b0e600bd7f4768f91992577734acb","question":"The audience clapped and cheered at the end of the show. What can you infer?","choices":["The show was terrible.","The show was enjoyed.","The show was canceled.","The show was too long."],"correct":1,"explanation":{"correct":"Answer: The show was enjoyed. When an audience claps and cheers, it is a sign of appreciation and excitement, which means the people watching the show liked it.","incorrect":[{"choice":"The show was terrible.","category":"contrary evidence","reason":"If the show were terrible, the audience would likely be quiet or show signs of disappointment, rather than clapping and cheering."},"",{"choice":"The show was canceled.","category":"illogical inference","reason":"People usually do not cheer when a show is canceled; cheering is a reaction to a positive performance, not a cancellation."},{"choice":"The show was too long.","category":"unsupported assumption","reason":"Clapping and cheering show positive feelings. There is no information in the sentence to suggest that the length of the show was an issue."}]},"studyAid":{"definition":"An inference is using clues from the text plus what you already know to figure out something that isn't directly stated.","example":"Text: 'He grabbed his umbrella.' Inference: It is likely raining outside. Text: 'She blew out the candles.' Inference: It is someone's birthday.","strategyClue":"Look at the reaction described in the sentence and ask yourself what kind of emotion usually causes people to act that way.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":13,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0014","version":3,"contentHash":"sha256:ca42bfb9f219d40670e5b8de06bda1b0ddcc92177d9d888c077013386c76f466","question":"Ben looked at his test paper, smiled, and gave a thumbs-up. What can you infer?","choices":["Ben failed the test.","Ben did well on the test.","Ben didn't finish.","Ben didn't study."],"correct":1,"explanation":{"correct":"Answer: Ben did well on the test. A thumbs-up is a universal sign of approval or success. Since Ben smiled after looking at his test, we can infer that he was happy with his results.","incorrect":[{"choice":"Ben failed the test.","category":"negative inference","reason":"A thumbs-up usually signifies success or happiness. Failing a test would typically result in a sad or frustrated facial expression, not a smile."},"",{"choice":"Ben didn't finish.","category":"unsupported inference","reason":"The text does not mention how much of the test was completed. A smile and a thumbs-up suggest completion and satisfaction, not an unfinished task."},{"choice":"Ben didn't study.","category":"unsupported inference","reason":"This choice makes an assumption about Ben's preparation that the text doesn't describe. The cues 'smiled' and 'thumbs-up' relate to his reaction to the grade, not his study habits."}]},"studyAid":{"definition":"An inference is using clues from the text and your own knowledge to figure out information that isn't directly stated.","example":"Text: The boy grabbed his umbrella before walking outside. Inference: It is raining or about to rain.","strategyClue":"Look for emotional clues (like smiling) and physical actions (like a thumbs-up), then ask yourself, 'In what situation would a person normally act this way?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":14,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0015","version":3,"contentHash":"sha256:f7f688d979e182c18c8b6b85a0420ed60d7282690c4492817c2ba0571bb54f88","question":"The kitchen smelled like garlic and tomatoes, and a pot was bubbling on the stove. What can you infer?","choices":["Someone was doing laundry.","Someone was cooking.","Someone was cleaning.","Someone was sleeping."],"correct":1,"explanation":{"correct":"Answer: Someone was cooking. An inference is a conclusion based on evidence. Since garlic, tomatoes, and a bubbling pot are all related to preparing food, this is the most logical conclusion.","incorrect":[{"choice":"Someone was doing laundry.","category":"unsupported by evidence","reason":"Laundry involves clothes and soap, not garlic and tomatoes. There is no evidence in the sentence to support this choice."},"",{"choice":"Someone was cleaning.","category":"unsupported by evidence","reason":"While cleaning might involve soap or supplies, it does not involve the smell of food or a bubbling pot on the stove."},{"choice":"Someone was sleeping.","category":"conflicts with evidence","reason":"A person who is sleeping would not be cooking on the stove. The details of the smell and the bubbling pot suggest active movement in the kitchen."}]},"studyAid":{"definition":"An inference is a smart guess you make by combining the facts in the text with what you already know from your own experiences.","example":"Text: 'The sky turned dark and gray.' Inference: It might rain soon. Text: 'She put on her coat and scarf.' Inference: It is cold outside.","strategyClue":"Look at each noun and verb in the sentence. Ask yourself, 'Where do these things usually belong?' and choose the activity that uses all those items together.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"return to the sentence clues before choosing","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":15,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0016","version":3,"contentHash":"sha256:2065d47a92317e8d75fc7009c7913c97e19726afc9507c0969cf1fcbc586260e","question":"Where would someone probably say the following? \"Julia, may I borrow your eraser?\"","choices":["store","kitchen","classroom","park"],"correct":2,"explanation":{"correct":"Answer: classroom. An eraser is a common tool used for schoolwork, so a classroom is the most logical setting for this request.","incorrect":[{"choice":"store","category":"setting mismatch","reason":"While you might buy an eraser at a store, you would ask to purchase one rather than 'borrow' one from someone you know personally."},{"choice":"kitchen","category":"unlikely context","reason":"Erasers are typically used for writing or drawing tasks, which are more common in a classroom or workspace than in a kitchen."},"",{"choice":"park","category":"unlikely context","reason":"While people can draw anywhere, a park is a place for outdoor recreation. 'Borrowing an eraser' implies a formal task like schoolwork found in a classroom."}]},"studyAid":{"definition":"To make an inference, use clues in the text and your own knowledge about the world to figure out information that isn't directly stated.","example":"If you see someone wearing a heavy coat, you can infer it is cold outside. If you see a student holding a lunchbox, you can infer it is time to eat.","strategyClue":"Look at the object mentioned in the question and ask yourself, 'Where do people usually use this item during their daily activities?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":16,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0017","version":3,"contentHash":"sha256:ccd437191e4c36ed2e24f6ec89117d1133c99eb6b743b543dbacfadccc0a300e","question":"Where would someone probably say the following? \"Swimmers take your mark, set, GO!\"","choices":["park","store","school","swimming pool"],"correct":3,"explanation":{"correct":"Answer: swimming pool. This phrase is a specific starting command used by referees or coaches to signal the beginning of a competitive swim race.","incorrect":[{"choice":"park","category":"setting mismatch","reason":"While people play in a park, this specific command is reserved for competitive water sports where swimmers dive into a pool to start a race."},{"choice":"store","category":"contextual error","reason":"A store is a place for shopping; this phrase is a race command, not something you would hear while buying groceries or items."},{"choice":"school","category":"inappropriate setting","reason":"Unless a student is participating in a swim meet at a school pool, this command is not used in a classroom or during a typical school day."},""]},"studyAid":{"definition":"An inference is a logical guess based on clues in the text and what you already know about the world.","example":"If someone holds an umbrella and walks in with wet shoes, you can infer it is raining outside.","strategyClue":"Identify the key action verbs or specific jargon in the phrase, then ask yourself, 'Where do I usually see people performing this specific activity?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":17,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0018","version":3,"contentHash":"sha256:bf6e0e13c0382ffb7c77205e107a512e662c753f60b35966df574f220f2e1418","question":"Where does the following event probably take place? Lupe put the milk back in the refrigerator.","choices":["kitchen","garage","bedroom","bathroom"],"correct":0,"explanation":{"correct":"Answer: kitchen. The refrigerator is an appliance used to store food, which is almost always located in a kitchen.","incorrect":["",{"choice":"garage","category":"uncommon appliance location","reason":"While some people keep an extra fridge in a garage, it is not the primary place where someone puts away milk as part of a daily routine."},{"choice":"bedroom","category":"inappropriate room usage","reason":"Refrigerators are meant for food storage, which does not belong in a sleeping area like a bedroom."},{"choice":"bathroom","category":"inappropriate room usage","reason":"Refrigerators are never kept in a bathroom because food storage should be kept separate from sanitation areas."}]},"studyAid":{"definition":"An inference is a logical guess based on clues from the text combined with what you already know about the world.","example":"If you see a character holding an umbrella and wearing boots, you can infer it is raining outside.","strategyClue":"Identify the key object in the sentence, then ask yourself: 'Where is this item usually found in a house?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":18,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0019","version":3,"contentHash":"sha256:27bd565bc05f5ded5c70e9a10293f7a256a81e64d01e060d23ddfe9ddd64ac7f","question":"Where do the following events probably take place? Everyone is supposed to stay seated, some face forward, and hold their backpacks on their laps.","choices":["train","airplane","a school bus","boat"],"correct":2,"explanation":{"correct":"Answer: a school bus. The presence of backpacks indicates students, and the instructions to sit forward and keep bags on laps are common rules for safety on a school bus.","incorrect":[{"choice":"train","category":"setting inconsistency","reason":"While you sit on a train, passengers are usually free to walk about or store bags in overhead bins rather than keeping them strictly on their laps."},{"choice":"airplane","category":"setting inconsistency","reason":"On an airplane, passengers are required to store bags under the seat in front of them, not on their laps, for safety reasons during takeoff and landing."},"",{"choice":"boat","category":"setting inconsistency","reason":"On a boat, there is rarely a rule requiring everyone to face forward or hold backpacks on their laps, as people often walk around to see the view."}]},"studyAid":{"definition":"An inference is using clues from the text and what you already know about the world to make a logical guess.","example":"Clue: 'The sky is dark and grey.' Inference: It might rain soon. Clue: 'I see a student carrying a backpack.' Inference: They are probably going to school.","strategyClue":"Look for specific keywords like 'backpacks' to identify the people involved, then ask yourself where those specific items are used most frequently in your daily life.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":19,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0020","version":3,"contentHash":"sha256:e203f134a803b9aeb14676ddf150bc68d3c52d1608a7e16b69d276c1cbd98e07","question":"Where do the following events probably take place? Go down the slide one at a time.","choices":["kitchen","a playground","classroom","store"],"correct":1,"explanation":{"correct":"Answer: a playground. Slides are common equipment found at playgrounds, which matches the activity of waiting for one's turn to go down a slide.","incorrect":[{"choice":"kitchen","category":"improper setting","reason":"Kitchens are for cooking and eating. You would not find a large outdoor slide inside a typical home kitchen."},"",{"choice":"classroom","category":"improper setting","reason":"While some classrooms have play areas, a 'slide' is an outdoor play structure, not a standard piece of classroom furniture for learning."},{"choice":"store","category":"improper setting","reason":"Stores are designed for shopping and browsing items. They do not have playground equipment like slides for customers to use."}]},"studyAid":{"definition":"An inference is using clues from the text to make a logical guess about something that isn't directly stated.","example":"If the text says 'I put on my raincoat and boots,' you can infer it is raining outside. If the text says 'The candles on the cake were lit,' you can infer it is a birthday party.","strategyClue":"Visualize the activity described in the sentence, then ask yourself where you have seen that object or action in real life.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":20,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0021","version":3,"contentHash":"sha256:fe41f0dd791fd4e154da3ad742fc689051ef138da1a6f1d25bebbb867649ace8","question":"Where does each event probably take place? John threw the ball to second base.","choices":["soccer game","basketball game","a baseball game","football game"],"correct":2,"explanation":{"correct":"Answer: a baseball game. The mention of 'second base' is a specific detail unique to baseball, which uses a diamond-shaped field with numbered bases.","incorrect":[{"choice":"soccer game","category":"sport rule mismatch","reason":"Soccer is played on a field with goals, not bases. Players primarily use their feet, not their hands, to throw a ball to a base."},{"choice":"basketball game","category":"sport rule mismatch","reason":"Basketball is played on a court with hoops. While you bounce the ball, there are no 'bases' to throw it to in a basketball game."},"",{"choice":"football game","category":"sport rule mismatch","reason":"Football is played on a field marked with yard lines and end zones. It does not use bases, so this setting does not match the clue."}]},"studyAid":{"definition":"An inference is using clues from the text and your own knowledge to figure out information that isn't directly stated.","example":"Clue: 'The waves crashed on the sand' -> Inference: The beach. Clue: 'She put on her goggles and dove in' -> Inference: The pool.","strategyClue":"Highlight the specific vocabulary words that belong to only one type of activity. Ask yourself, 'Which of these sports uses this specific word in its rules?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":21,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0022","version":3,"contentHash":"sha256:e9894001712ec3b6b72a577b9a4439c2092c907f95ed22b201d39b380189abcc","question":"Where does each event probably take place? She fastened her seat belt when she sat down.","choices":["boat","train","bus","an airplane or car"],"correct":3,"explanation":{"correct":"Answer: an airplane or car. Seat belts are standard safety features primarily designed for use in vehicles like airplanes and cars to secure passengers during travel.","incorrect":[{"choice":"boat","category":"contextual mismatch","reason":"Most standard boats do not have seat belts for passengers; while some specialized racing boats might, a regular boat trip typically does not require fastening a seat belt."},{"choice":"train","category":"contextual mismatch","reason":"In most passenger trains, you are free to walk around the cabin while the train is moving, as they generally do not provide or require seat belts for passengers."},{"choice":"bus","category":"contextual mismatch","reason":"While school buses are beginning to add them, standard city buses and motorcoaches do not typically provide seat belts for passengers to fasten upon sitting down."},""]},"studyAid":{"definition":"An inference is a logical guess based on clues in the text and what you already know about how the world works.","example":"If the text says 'He put on his goggles before jumping in,' we infer he is at a pool. If the text says 'The candles melted on the cake,' we infer it is a birthday party.","strategyClue":"Think about the specific object mentioned in the sentence. Ask yourself: 'In which transportation settings is this object required for safety by law or design?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":22,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0023","version":3,"contentHash":"sha256:ba7a7d61d9cd1cfe03ab7e8e5c88897ea8228902c9f2ff7a2569e3c8d5babc98","question":"Where do the following events probably take place? You can renew your book, or you can check out a new one.","choices":["museum","a library","bookstore","classroom"],"correct":1,"explanation":{"correct":"Answer: a library. Libraries are public places that specifically allow you to check out books and renew them after you have borrowed them.","incorrect":[{"choice":"museum","category":"incorrect location purpose","reason":"While museums have exhibits and items to view, they do not have a checkout or renewal system for books."},"",{"choice":"bookstore","category":"incorrect purchase logic","reason":"At a bookstore, you buy books to keep permanently rather than checking them out to return later."},{"choice":"classroom","category":"incorrect setting function","reason":"While a classroom might have a bookshelf, it does not provide a formal system for renewing and checking out books like a library does."}]},"studyAid":{"definition":"An inference is using clues from the text and what you already know about the world to figure out information that isn't directly stated.","example":"If a character is wearing a raincoat and carrying an umbrella, we can infer it is raining outside.","strategyClue":"Focus on the specific actions of checking out and renewing. Ask yourself: 'In which location are these specific tasks the primary purpose of the building?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":23,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0024","version":3,"contentHash":"sha256:ddfd062a5834d127c2876081b7450f13fa6a4403eb3245977ff85c31f1b0ded7","question":"Where do the following events probably take place? The runner slid into home plate and was safe!","choices":["football game","a baseball game","basketball game","soccer game"],"correct":1,"explanation":{"correct":"Answer: a baseball game. The term 'home plate' and the action of sliding to reach it safely are specific components unique to baseball.","incorrect":[{"choice":"football game","category":"incorrect sport terminology","reason":"Football games involve touchdowns and goal lines, not home plates or sliding to reach a base."},"",{"choice":"basketball game","category":"incorrect sport terminology","reason":"In basketball, players dribble and shoot into hoops; there are no bases or home plates to slide into."},{"choice":"soccer game","category":"incorrect sport terminology","reason":"Soccer involves kicking a ball into a net and does not include the action of sliding into a home plate."}]},"studyAid":{"definition":"An inference is a logical conclusion made by combining the details in the text with what you already know about the world.","example":"If you read that someone is wearing a swimsuit and carrying a towel, you can infer they are going to the pool or beach.","strategyClue":"Look for specific nouns or actions in the sentence, then ask yourself which sport is the only one that uses those exact terms.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":24,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0025","version":3,"contentHash":"sha256:c7f97609dc4dbc85deb5748e271eddd0c333c34438b2836f99363349c0379c42","question":"Where do the following events probably take place? The waitress came to the table to take our order.","choices":["store","park","school","restaurant"],"correct":3,"explanation":{"correct":"Answer: restaurant. A waitress is a professional who serves food and takes customer orders at a table, which is a service found specifically in a restaurant.","incorrect":[{"choice":"store","category":"setting mismatch","reason":"While stores have employees, they are usually called clerks or cashiers, and they do not typically take food orders at a table."},{"choice":"park","category":"setting mismatch","reason":"A park is an outdoor recreational area. You might bring food to a park, but there is no staff there to take your order at a table."},{"choice":"school","category":"setting mismatch","reason":"In a school, students go to a cafeteria line to get food. Teachers or staff do not come to a table to take your specific order."},""]},"studyAid":{"definition":"Making an inference means using clues from the text and what you already know about the world to figure out information that isn't directly stated.","example":"Clue: 'We put on our swimsuits.' Inference: We are going to the pool or beach. Clue: 'The bell rang and students sat at their desks.' Inference: We are in a classroom.","strategyClue":"Look at the key noun ('waitress') and the action ('take our order'). Ask yourself, 'Where do I usually see this person and what are they doing?'","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":25,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0026","version":3,"contentHash":"sha256:789f9072e39f16819a939f3368d60ccc436356a3a1c6b15b47aaac580112ef08","question":"Where do the following events probably take place? Mrs. Alvarez passed out glue for our art project.","choices":["kitchen","classroom","store","park"],"correct":1,"explanation":{"correct":"Answer: classroom. An art project requiring glue is a standard activity done in a classroom setting where students typically follow a teacher's instructions.","incorrect":[{"choice":"kitchen","category":"setting mismatch","reason":"While glue is sometimes used at home, Mrs. Alvarez is a title typically used for a teacher. A kitchen is usually for cooking, not for structured school art projects."},"",{"choice":"store","category":"action mismatch","reason":"People visit stores to buy items. A store clerk would not be 'passing out glue' for an art project; this action implies a teacher-student relationship."},{"choice":"park","category":"environment mismatch","reason":"Parks are public outdoor recreational areas. It is unlikely that school materials like glue would be distributed for a project in an outdoor park setting."}]},"studyAid":{"definition":"Making an inference means using the clues in a sentence to figure out information that is not directly stated.","example":"Clue: 'We put on swimsuits.' Inference: We are going to a pool or beach. Clue: 'The pilot flew the plane.' Inference: We are at an airport.","strategyClue":"Identify the key action (passing out glue) and the role of the person (Mrs. Alvarez). Ask yourself where these two things usually happen together.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":26,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0027","version":3,"contentHash":"sha256:0ce7ff30cf8719e7106b22e78f05bb6a24a48f2c3ae6fced60280d153a44acf7","question":"Where would someone probably say the following? \"Fasten your seat belts.\"","choices":["train","in an airplane (or car)","boat","bus"],"correct":1,"explanation":{"correct":"Answer: in an airplane (or car). Seat belts are safety devices used in vehicles where speed and sudden stops are common, making them essential equipment for passengers.","incorrect":[{"choice":"train","category":"contextual setting mismatch","reason":"Most trains do not have seat belts for passengers, as they move differently and generally do not require them for safety during standard travel."},"",{"choice":"boat","category":"contextual setting mismatch","reason":"While boats have life vests, they rarely use seat belts because passengers are often expected to be able to move around the deck."},{"choice":"bus","category":"contextual setting mismatch","reason":"Most traditional city buses do not provide seat belts for passengers, making this an unlikely place to hear that specific instruction."}]},"studyAid":{"definition":"An inference is a logical conclusion you draw based on clues in the text combined with what you already know about the world.","example":"If you see a character holding an umbrella and wearing a raincoat, you can infer it is raining outside.","strategyClue":"Think about the specific items or safety gear used in different types of travel, and ask yourself which vehicle requires you to lock yourself into a seat for safety.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sequence":27,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0028","version":3,"contentHash":"sha256:ba2dcbc379b486f545882582d9de05df35636c571d391a3b486ef65db1790603","question":"Where would someone probably say the following? \"The sign says not to feed the animals.\"","choices":["park","at a zoo","aquarium","farm"],"correct":1,"explanation":{"correct":"Answer: at a zoo. Signs warning visitors not to feed the animals are most common at zoos, where zookeepers strictly control animal diets to keep them healthy.","incorrect":[{"choice":"park","category":"Inference error","reason":"While some parks have animals like ducks, they rarely use formal signs asking people not to feed them. The warning is specific to the managed environment of a zoo."},"",{"choice":"aquarium","category":"Inference error","reason":"Aquariums primarily house fish and marine life behind glass tanks. Because the animals are physically inaccessible, you wouldn't typically see a 'do not feed' sign there."},{"choice":"farm","category":"Inference error","reason":"Farms are places where animals are raised, and you are usually invited to feed them or interact with them, making this sign very unlikely."}]},"studyAid":{"definition":"An inference is a logical conclusion made by combining information from the text with what you already know about the world.","example":"Text: 'She grabbed her umbrella.' Inference: It is likely raining outside. Text: 'The alarm clock beeped.' Inference: It is time to wake up.","strategyClue":"Think about the purpose of the sign and match the setting that is most likely to have strict rules about human interaction with living creatures.","link":"https://www.readingrockets.org/article/making-inferences","linkText":"Reading Rockets - Inference"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":75,"reviewPriority":"high","sourceSet":"reading-comprehension-inference","sequence":28,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0029","version":3,"contentHash":"sha256:1eacef04905e2dacd48064ac2b0f4e31b5d49607f1954c3eb427c327ab4555e9","question":"Read the story. Sarah was going to the amusement park. She was so excited! She told all her friends that she was going to ride the merry-go-round, the Ferris wheel, and the bumper cars. What other ride would Sarah go on at the amusement park?","choices":["pet the rabbits","win a prize","ride the giraffe","roller coaster"],"correct":3,"explanation":{"correct":"Answer: roller coaster. This is the correct choice because a roller coaster is a standard, classic ride found at amusement parks, fitting the context of the story's list of rides.","incorrect":[{"choice":"pet the rabbits","category":"not a ride","reason":"While you might find rabbits at a park, petting them is an activity, not a ride like the merry-go-round or Ferris wheel."},{"choice":"win a prize","category":"activity vs ride","reason":"Winning a prize usually happens at a carnival game booth, whereas the other examples listed are types of mechanical amusement rides."},{"choice":"ride the giraffe","category":"unrealistic expectation","reason":"Giraffes are live animals and are not amusement park rides; you cannot ride them at a park."},""]},"studyAid":{"definition":"Comprehension involves identifying items that belong to the same category, such as 'amusement park rides'.","example":"Category: Fruit (apple, banana, orange); Category: Sports (soccer, basketball, tennis).","strategyClue":"Look at the items already listed in the text—merry-go-round, Ferris wheel, and bumper cars—and choose an item that belongs to that exact same group.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":1,"sourceCategory":"reading-test","sourceGrade":3,"sequence":29,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0030","version":3,"contentHash":"sha256:6168098686780d8cf1f7f1dc3b137658d661302f7526224fcc78c514f742782d","question":"Pigs will eat almost anything. They eat meat and plants. What do pigs eat?","choices":["water","plants and meat","mud","pizza"],"correct":1,"explanation":{"correct":"Answer: plants and meat. The text explicitly states, 'They eat meat and plants.' Therefore, these are the two food items identified in the passage.","incorrect":[{"choice":"water","category":"not in text","reason":"While pigs drink water, the passage specifically discusses what they eat, and 'water' is not mentioned as a food source in the text provided."},"",{"choice":"mud","category":"misinterpreted context","reason":"Pigs may play in mud to stay cool, but the passage identifies 'meat and plants' as their food, not mud."},{"choice":"pizza","category":"not in text","reason":"Even if a pig might eat pizza, you must only answer based on what the text says. The text lists meat and plants, not pizza."}]},"studyAid":{"definition":"Reading comprehension means finding the specific answers to questions directly inside the text provided.","example":"Text: 'The cat likes milk and fish.' Question: 'What does the cat like?' Answer: 'milk and fish.' (Not 'water' or 'cat food'.)","strategyClue":"Scan the text for keywords from the question, such as 'eat'. Once you find those words, look immediately before or after them for the specific details you need.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":3,"sourceCategory":"reading-test","sourceGrade":3,"sequence":30,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0031","version":3,"contentHash":"sha256:10c7bf6ba7b794621f4a45841c07fd476ac0c42535046ad088def53eca2781ee","question":"Read the passage. Oceanville was a small town on the Pacific Coast. One day the radio broadcast issued an urgent storm warning. The people ____________. Fill in the blank with the best answer.","choices":["changed the radio station","went to the grocery store","prepared for the storm","went out on a sail boat"],"correct":2,"explanation":{"correct":"Answer: prepared for the storm. Since the radio broadcasted an 'urgent storm warning,' the most logical and safe action for the people is to get ready for the severe weather.","incorrect":[{"choice":"changed the radio station","category":"illogical inference","reason":"If the news is an urgent warning about a storm, changing the channel would keep people from hearing important safety information they need."},{"choice":"went to the grocery store","category":"contextual mismatch","reason":"While people sometimes go to the store, in the context of an 'urgent' warning, it is safer to stay home or prepare indoors rather than running errands."},"",{"choice":"went out on a sail boat","category":"unsafe decision","reason":"Going out on a boat during an urgent storm warning is very dangerous; people would avoid the water when a storm is approaching."}]},"studyAid":{"definition":"Comprehension means using the clues in a story to choose actions that make sense for the characters and the situation.","example":"If a character is cold, they might put on a sweater (logical) rather than jump in a pool (illogical).","strategyClue":"Look at the adjectives and nouns in the previous sentence to determine the mood, then select the action that matches that specific situation.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":6,"sourceCategory":"reading-test","sourceGrade":3,"sequence":31,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0032","version":4,"contentHash":"sha256:d5ebd59241bd81fd73a017faecdc3eea2ecca0b881371e0506b83aadc53860ec","question":"Choose the missing word. I can ___________ the rock to make it shiny.","choices":["hide","dig","throw","polish"],"correct":3,"explanation":{"correct":"Answer: polish. To 'polish' an object is to rub it until it becomes smooth and shiny, which logically matches the outcome mentioned in the sentence.","incorrect":[{"choice":"hide","category":"verb meaning error","reason":"Hiding a rock would place it out of sight, but it would not make the surface shiny. Look for a verb that describes a physical change to the object's appearance."},{"choice":"dig","category":"verb meaning error","reason":"Digging usually involves moving dirt or soil. This action does not make a rock shiny; 'polish' is the specific action used for improving the texture and look of a surface."},{"choice":"throw","category":"verb meaning error","reason":"Throwing a rock changes its location, but it does not change the rock's surface condition. Use 'polish' when describing the process of making something gleam."},""]},"studyAid":{"definition":"Verbs are action words. Choosing the correct verb depends on understanding which action leads to the specific result described in the sentence.","example":"He had to polish the silver until it glowed. She will wash the dishes to make them clean.","strategyClue":"Focus on the end result mentioned—'make it shiny.' Ask yourself which of the actions listed is the direct cause of making a surface look bright and reflective.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":7,"sourceCategory":"reading-test","sourceGrade":3,"sequence":32,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0033","version":3,"contentHash":"sha256:4721182ec0df9158bfbb7ea35ba7d25e5ac5f743faf06d254e270973cda8ef5b","question":"Choose the word that matches the picture and fits the sentence. The ________ has a new skirt.","choices":["boy","girl","dog","skirt"],"correct":1,"explanation":{"correct":"Answer: girl. The sentence describes someone who 'has a new skirt.' A girl is the most appropriate subject noun to fit this context, as skirts are typically worn by girls.","incorrect":[{"choice":"boy","category":"gender context mismatch","reason":"While a boy is a person, boys do not typically wear skirts. 'Girl' is a better fit for the sentence based on the context of the clothing item mentioned."},"",{"choice":"dog","category":"noun category mismatch","reason":"A dog is an animal and does not wear skirts. The sentence requires a noun that can realistically possess or wear the item described."},{"choice":"skirt","category":"redundant noun usage","reason":"It would be repetitive to say 'The skirt has a new skirt.' The subject needs to be the person who owns or wears the skirt, not the item itself."}]},"studyAid":{"definition":"A noun names a person, place, or thing. To choose the right noun for a sentence, ensure the subject makes logical sense with the action or object described.","example":"Correct: The chef cooks dinner. Incorrect: The table cooks dinner.","strategyClue":"Look at the object mentioned at the end of the sentence. Ask yourself: 'Who or what would naturally be associated with this object?' and match that to the choices.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":11,"sourceCategory":"reading-test","sourceGrade":3,"sequence":33,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0034","version":3,"contentHash":"sha256:89edeb88f01e51472d054fb9960140e2b1764c7a07afc79f8cd34f75ba79b147","question":"Read the following. Maria went to the store with her mother. Maria bought an apple to eat for a snack. Her mother bought eggs to make cookies. What are all of the items both Maria and her mother bought at the store?","choices":["Maria and her mother bought apples.","Maria’s mother bought eggs.","Maria bought apples.","Maria and her mother bought eggs and apples."],"correct":3,"explanation":{"correct":"Answer: Maria and her mother bought eggs and apples. By identifying all nouns representing items purchased by both characters in the text, we see Maria bought an apple and her mother bought eggs.","incorrect":[{"choice":"Maria and her mother bought apples.","category":"incomplete information","reason":"This choice misses the eggs that the mother purchased. To find the complete list, look for all items bought by anyone in the story."},{"choice":"Maria’s mother bought eggs.","category":"incomplete information","reason":"This choice identifies the items bought by the mother but ignores the apple that Maria purchased. Be sure to check both characters mentioned in the text."},{"choice":"Maria bought apples.","category":"incomplete information","reason":"This only accounts for Maria's actions. The question asks for the items bought by *both* Maria and her mother, requiring you to look at the whole story."},""]},"studyAid":{"definition":"To answer reading comprehension questions, you must gather facts from the entire text rather than just focusing on one sentence or one character.","example":"If the story says 'Sam has a blue ball and Pat has a red truck,' the answer to 'What toys do they have?' includes both items.","strategyClue":"Underline every item mentioned after a verb like 'bought' or 'had' as you read. After reading the whole paragraph, combine all your underlined items into one final list.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":14,"sourceCategory":"reading-test","sourceGrade":3,"sequence":34,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0035","version":3,"contentHash":"sha256:9cfc225d542b825093032efa643d629b3aaa213aca449b094e5210c597284e61","question":"Match the pictures to the word below.","choices":["cupcake","cake","cupboard","pancake +"],"correct":0,"explanation":{"correct":"Answer: cupcake. The word 'cupcake' accurately describes the picture of a small cake baked in a cup-shaped container, matching both parts of the compound word.","incorrect":["",{"choice":"cake","category":"too general","reason":"While a cupcake is a type of cake, this word is too broad and does not account for the specific 'cup' portion of the image."},{"choice":"cupboard","category":"incorrect compound","reason":"A cupboard is a piece of furniture for storage. Even though it contains the word 'cup', it does not describe the food shown."},{"choice":"pancake +","category":"mismatched visual description","reason":"A pancake is a flat, round cake cooked on a griddle. This word does not fit the shape or the preparation style of the item in the picture."}]},"studyAid":{"definition":"Compound words are formed when two smaller words join together to create a new word with a specific meaning.","example":"cup + cake = cupcake; rain + bow = rainbow; tooth + brush = toothbrush","strategyClue":"Break the image into two distinct parts and look for a word that combines the names of both parts into one noun.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":15,"sourceCategory":"reading-test","sourceGrade":3,"sequence":35,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0040","version":3,"contentHash":"sha256:2fddd26edaee62ba06b44204f489be37c3713084a4f618f9801c2602403500fc","question":"Read the following. Mary went to a new school on Monday. She did not know anyone in her class. She wanted to go home. You can tell in the story that Mary is _______________.","choices":["sad","happy","hungry","tired"],"correct":0,"explanation":{"correct":"Answer: sad. The story mentions Mary does not know anyone and wants to go home, which are classic signs of feeling lonely, nervous, or sad when starting at a new school.","incorrect":["",{"choice":"happy","category":"opposite character state","reason":"If Mary were happy, she would likely be excited to meet new people rather than wanting to go home."},{"choice":"hungry","category":"unsupported by context","reason":"The story does not mention Mary wanting food or having an empty stomach, so there is no evidence for this feeling."},{"choice":"tired","category":"incorrect emotional inference","reason":"While Mary might be tired, her desire to 'go home' and lack of friends suggests she is feeling sad or uneasy about the new situation rather than sleepy."}]},"studyAid":{"definition":"Inferencing is using clues in a story to figure out something that the author does not directly state.","example":"If a character is shivering, you can infer they are cold. If a character says 'yuck' to a meal, you can infer they do not like it.","strategyClue":"Look at the character's actions and thoughts in the sentences. Ask yourself, 'What kind of person would act this way or feel this way?' to find the right emotion.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":20,"sourceCategory":"reading-test","sourceGrade":3,"sequence":40,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0041","version":3,"contentHash":"sha256:fee1e1eafa713a71bfe3a21f7aec1e9c76ccbe72765c28a3b3a221294b13aa6e","question":"Read the story.. Mindy and Matt had been hiking all day long. They had covered 17 miles, hills included. By dusk they had finally stopped. Mindy immediately grabbed her water bottle. Matt took out fruit juice and lemonade From the above passage, you can tell that:","choices":["Mindy and Matt were hungry.","Mindy and Matt were tired.","Mindy and Matt were going home.","Mindy and Matt were thirsty."],"correct":3,"explanation":{"correct":"Answer: Mindy and Matt were thirsty. The passage highlights physical exertion, specifically mentioning they hiked 17 miles, and describes Mindy grabbing water while Matt took out fruit juice and lemonade, both of which are liquids used to quench thirst.","incorrect":[{"choice":"Mindy and Matt were hungry.","category":"lacks text evidence","reason":"While the passage shows them taking a break, the specific items mentioned are beverages, not food. We look for textual evidence that directly supports the characters' actions."},{"choice":"Mindy and Matt were tired.","category":"unsupported by specific action","reason":"While hiking 17 miles would likely make anyone tired, the text focuses specifically on the act of drinking. Always look for the conclusion best supported by the characters' primary action in the final sentence."},{"choice":"Mindy and Matt were going home.","category":"not in passage","reason":"The text mentions they stopped at dusk, but it does not describe them packing up or starting a journey back. This choice assumes information not present in the passage."},""]},"studyAid":{"definition":"Making an inference means using clues from the text and what you already know to reach a logical conclusion that isn't explicitly stated.","example":"If the author says a character is shaking and teeth are chattering, you can infer the character is cold.","strategyClue":"Look at the specific items the characters are interacting with in the final sentence and think about the physical need those items satisfy.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":21,"sourceCategory":"reading-test","sourceGrade":3,"sequence":41,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0043","version":3,"contentHash":"sha256:d48607f83e9dc5685e0825bc1ec4fe924f26439a2299b09057ab47d4176d2883","question":"Read the sentence and choose the correct word. The wind ________ the leaves off the trees.","choices":["they","blew","blue","boil"],"correct":1,"explanation":{"correct":"Answer: blew. The verb 'blew' is the correct past-tense form of 'blow' to describe the action of the wind moving the leaves.","incorrect":[{"choice":"they","category":"incorrect part of speech","reason":"The word 'they' is a pronoun used for people or things, not an action. The sentence needs an action word (verb) here to show what the wind did."},"",{"choice":"blue","category":"homophone confusion","reason":"The word 'blue' is a color, not an action. Use 'blew' when describing the past action of air moving."},{"choice":"boil","category":"incorrect verb tense","reason":"The word 'boil' describes heating liquid, which doesn't make sense in this context. Even if it did, the sentence describes an action that already happened, so 'boiled' would be needed."}]},"studyAid":{"definition":"Verbs are action words that describe what a person, animal, or thing is doing. Sometimes verbs change their spelling to show that the action happened in the past.","example":"He runs today vs. He ran yesterday; The wind blows today vs. The wind blew yesterday.","strategyClue":"Ask yourself, 'Is this word an action?' and 'Did this happen in the past?' before checking which word matches the spelling of the past-tense action.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":23,"sourceCategory":"reading-test","sourceGrade":3,"sequence":43,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0048","version":3,"contentHash":"sha256:0e6116df1c121c8683fbe8781dcdefb55ff088f1dfb7d8694d62289f069dba35","question":"Read the following. John went to visit his grandma. He saw cows, horses, and pigs. He helped his grandma pick apples. John is at a _______________.","choices":["school","zoo","circus","farm"],"correct":3,"explanation":{"correct":"Answer: farm. The presence of cows, horses, and picking apples describes a rural setting where animals are raised and food is grown, which is the definition of a farm.","incorrect":[{"choice":"school","category":"setting mismatch","reason":"Schools are places for learning in classrooms, not for keeping farm animals like cows or picking apples from trees."},{"choice":"zoo","category":"setting mismatch","reason":"While you might see cows or horses at a petting zoo, you generally do not help pick apples there, and a farm is the more specific home for these animals and activities."},{"choice":"circus","category":"setting mismatch","reason":"A circus is a place for performances and shows. Cows, horses, and apples are typically associated with agricultural life, not a traveling show."},""]},"studyAid":{"definition":"To identify a setting, look for clues about the activities and objects present in a story.","example":"If you see a blackboard and desks, the setting is a school. If you see waves and sand, the setting is a beach.","strategyClue":"Underline every animal or item mentioned in the text. Ask yourself, 'Where do these things usually belong together in the real world?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":28,"sourceCategory":"reading-test","sourceGrade":3,"sequence":48,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0051","version":3,"contentHash":"sha256:3848d3525798449113c13ae7f83d703bd36b4174022e06603892441ecbefff47","question":"Identify the compound word.","choices":["little","popcorn","helpful","poc ket"],"correct":1,"explanation":{"correct":"Answer: popcorn. A compound word is formed when two smaller words are joined together to make a new word. 'Pop' and 'corn' are both real words that combine to create 'popcorn'.","incorrect":[{"choice":"little","category":"not a compound","reason":"Although 'little' is a word, it cannot be split into two separate, smaller words that have their own meanings."},"",{"choice":"helpful","category":"base and suffix","reason":"'Helpful' is made of a base word and a suffix ('-ful'), not two independent words joined together."},{"choice":"poc ket","category":"invalid word spacing","reason":"This is a single word ('pocket') that has been split incorrectly. 'Poc' is not a real word."}]},"studyAid":{"definition":"A compound word is a word made by joining two smaller words together to create a new meaning.","example":"sun + flower = sunflower, pan + cake = pancake, rain + bow = rainbow","strategyClue":"Look at each choice and try to cut it into two pieces. If both pieces are real words that create a new meaning when put together, you have found a compound word.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":31,"sourceCategory":"reading-test","sourceGrade":3,"sequence":51,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0052","version":3,"contentHash":"sha256:749480661671abc70f2074abe9d0a41c9844a23c3854725ca8ac880c3059b5a5","question":"Read the story. Perry randown the stairs. He hurried into the kitchen. His mother had forgotten to leave his lunch on the table. He looked in the fridge. Oh no, he thought. Mother forgot to make lunch for me. He ran out the door and started towards the waiting school bus. What is Perry’s problem in the story?","choices":["Perry’s mother did not make a lunch for him.","Perry is late for school.","Perry’s mother isn’t home.","Pe rry forgot his lunch."],"correct":0,"explanation":{"correct":"Answer: Perry’s mother did not make a lunch for him. The text specifically states, 'Mother forgot to make lunch for me,' which explains why Perry is experiencing the problem.","incorrect":["",{"choice":"Perry is late for school.","category":"misinterpreted story detail","reason":"While Perry runs to the school bus, the story does not mention that he is late. Focus on the specific information provided about the missing lunch."},{"choice":"Perry’s mother isn’t home.","category":"unsupported story inference","reason":"The text says his mother forgot to leave his lunch, but it never states that she is away from the house. Do not add information that isn't in the story."},{"choice":"Pe rry forgot his lunch.","category":"incorrect character blame","reason":"The story tells us that his mother forgot to make the lunch, not that Perry forgot it himself. Be careful to identify who performed the action mentioned."}]},"studyAid":{"definition":"To answer comprehension questions, look for explicit evidence in the text that directly supports your conclusion.","example":"Text: 'The sky turned dark and rain began to fall.' Question: Why did they go inside? Answer: Because it started raining.","strategyClue":"Highlight the sentence in the text where the main character expresses their concern, then compare that sentence to each choice to see which one matches the stated cause.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":32,"sourceCategory":"reading-test","sourceGrade":3,"sequence":52,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0055","version":3,"contentHash":"sha256:731c9b871406e6b4de444cb9e6970e9eaa7def74d881b71ac3ba6f88c9961718","question":"What is the prefix in the word disagree?","choices":["agree","disa","dis","sage"],"correct":2,"explanation":{"correct":"Answer: dis. A prefix is a letter or group of letters added to the beginning of a root word to change its meaning. Here, 'dis-' is added to the base word 'agree'.","incorrect":[{"choice":"agree","category":"root word identification","reason":"'Agree' is actually the base word, not the prefix. The prefix is the part attached to the very front to create the new word."},{"choice":"disa","category":"incorrect prefix boundary","reason":"While 'disa' contains the prefix, it includes an extra 'a' that is part of the root word. A prefix must be a distinct unit that attaches to the complete root word."},"",{"choice":"sage","category":"not a prefix","reason":"'Sage' is not a prefix; it is a separate word. It does not appear at the beginning of 'disagree' to change the meaning of the root."}]},"studyAid":{"definition":"A prefix is a word part added to the front of a base word that creates a new meaning, often representing 'not' or 'opposite'.","example":"dis- + agree = disagree; un- + happy = unhappy; re- + play = replay","strategyClue":"Look at the word and identify the base word that would remain if you removed the beginning part. The part you removed that changes the root's meaning is your prefix.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":35,"sourceCategory":"reading-test","sourceGrade":3,"sequence":55,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0058","version":3,"contentHash":"sha256:1ecea87fd338b2050ab07e821fb1251cea008e5e56b35ac3056df1be64058d2d","question":"Identify the correct suffix. h appy, h app ier, h app i___","choices":["ly","er","est","tion"],"correct":2,"explanation":{"correct":"Answer: est. When comparing three or more things, we change the adjective 'happy' to its superlative form by changing the 'y' to 'i' and adding 'est' to create 'happiest'.","incorrect":[{"choice":"ly","category":"adverb formation","reason":"Adding 'ly' creates the adverb 'happily', which describes how an action is done. It does not fit the pattern of degree comparison established by 'happier'."},{"choice":"er","category":"comparative suffix","reason":"The word 'happier' already uses the 'er' suffix to compare two things. Since the prompt asks to complete the sequence of degree, we need the superlative suffix instead."},"",{"choice":"tion","category":"noun suffix","reason":"Adding 'tion' turns a verb into a noun. This suffix does not work with adjectives like 'happy' to show comparison."}]},"studyAid":{"definition":"To compare adjectives, add 'er' for two things (comparative) and 'est' for three or more things (superlative). If the word ends in 'y', change the 'y' to 'i' before adding the suffix.","example":"fast -> faster -> fastest; funny -> funnier -> funniest; silly -> sillier -> silliest","strategyClue":"Look at the pattern in the list: first is the base word, second is the comparative form, so the third must be the superlative form used for the most or the extreme version.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":38,"sourceCategory":"reading-test","sourceGrade":3,"sequence":58,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0060","version":3,"contentHash":"sha256:c7f9b97add1f9c37710ba753ae78cdbdb4453bcda6e90f6d447717973b4b59d6","question":"Read the label. The label says to use the cleaner on:","choices":["carpets","doors, walls and ceilings","counters, windows, and stove tops","wood floors"],"correct":2,"explanation":{"correct":"Answer: counters, windows, and stove tops. Based on the label text, these are the specific surfaces listed for use with this cleaning product.","incorrect":[{"choice":"carpets","category":"not in text","reason":"The label does not mention carpets. Be sure to check that your answer is explicitly stated in the provided text."},{"choice":"doors, walls and ceilings","category":"not in text","reason":"The label does not list these areas. Avoid using outside knowledge or assumptions; stick only to what the label confirms."},"",{"choice":"wood floors","category":"not in text","reason":"Wood floors are not included on the label's list of appropriate surfaces for this cleaner."}]},"studyAid":{"definition":"Reading comprehension means finding the specific details or facts provided directly in a text.","example":"If a sign says 'No dogs allowed in the park,' then 'dogs are not permitted' is a fact; 'cats are not permitted' is not stated.","strategyClue":"Scan the text for keywords from each choice. Only select the option where every item listed is mentioned directly in the provided label.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"basic-1_reading.pdf","sourceQuestionNumber":40,"sourceCategory":"reading-test","sourceGrade":3,"sequence":60,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0112","version":3,"contentHash":"sha256:6a45ba367d87fabc72c26a965c6d25bce8ff4b1cde7dc7503ffbc62086575ebd","question":"Read the wedding announcement. Who officiated at the ceremony?","choices":["Linda Milam","Janet Thompson","Darren Andree","Thompson Andree"],"correct":0,"explanation":{"correct":"Answer: Linda Milam. The announcement explicitly identifies Linda Milam as the person who officiated the ceremony.","incorrect":["",{"choice":"Janet Thompson","category":"Incorrect reading identification","reason":"This person may be mentioned elsewhere in the text, but the announcement does not identify her as the officiant."},{"choice":"Darren Andree","category":"Incorrect reading identification","reason":"The text lists Darren Andree as a participant in the ceremony, not as the person performing the duties of the officiant."},{"choice":"Thompson Andree","category":"Misreading names","reason":"This appears to be a combination of other names mentioned in the text rather than the name of the individual who officiated."}]},"studyAid":{"definition":"Comprehension questions ask you to find specific information directly stated in a text.","example":"If a story says, 'The red dog ran home,' and you are asked who ran home, you find the subject of the sentence: 'The red dog.'","strategyClue":"Scan the text for the keyword 'officiated' or synonyms like 'performed by.' Once you find the word, look at the name directly next to it.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":10,"sourceCategory":"reading-test","sourceGrade":3,"sequence":112,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0117","version":3,"contentHash":"sha256:c0ced19e6c76731fd25b3fa7d86756451c8b4efa26eb1537ed1b44f48a7dbd60","question":"Read the following passage. Hol t, Reinhart, and Winston. 1997. Which statement does not explain why the man stopped at the Bed and Breakfast?","choices":["There were chrysanthemums in the window.","There was a fire in the fireplace.","There was a dachshund asleep in front of the fireplace.","He was exhausted, hungry and cold."],"correct":3,"explanation":{"correct":"Answer: He was exhausted, hungry and cold. This statement describes the man's internal physical state, not a visual cue that caught his attention, and therefore does not explain why he paused at the establishment.","incorrect":[{"choice":"There were chrysanthemums in the window.","category":"visual observation","reason":"This detail explains the man's attention because it is a specific, attractive sight he observed while looking at the building."},{"choice":"There was a fire in the fireplace.","category":"inviting detail","reason":"This explains his interest because it suggests warmth and comfort, which are reasons a traveler would be drawn to stop at an inn."},{"choice":"There was a dachshund asleep in front of the fireplace.","category":"welcoming observation","reason":"This is a reason for his interest as it suggests the building is a peaceful, lived-in home, which adds to the inviting nature of the place."},""]},"studyAid":{"definition":"To identify why a character takes an action, look for details in the text that describe what they see or feel that motivates their decision.","example":"If a girl buys an umbrella because she sees dark clouds, the 'reason' is the clouds. 'The sky is blue' is not a reason she bought the umbrella.","strategyClue":"Look at each option and ask yourself: 'Did the character see or experience this detail, and did it make him want to stop?' Eliminate options that clearly acted as motivators for his decision.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":15,"sourceCategory":"reading-test","sourceGrade":3,"sequence":117,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0124","version":3,"contentHash":"sha256:ebd82f9de191f854175519cc7a7f7da05f3399d27e8951a09018e8f299bd1700","question":"Read the passage. In 186 2, David Glasgow Farragut was the commander of a fleet of 17 ships sent to blockade the mouth of the Mississippi River. He set out to capture New Orleans, the South’s largest city and busiest port. To get to the city Admiral Farragut had to pass two heavily armed Confederate forts. In addition, a chain of hulks (old ships) was laid across the Mississippi to keep Yankee ships out. “Nothing afloat could pass the forts,” said a citizen of New Orleans. Farragut’s fleetheaded up the river. The Confederates opened fire. One ship was hit 42 times. Farragut’s flagship was set ablaze. “The passing of the forts…was one of the most awful sights and events I ever saw… [it] “Ruler of the P resident’s Navy”, Oxford University Press, O xford, New York, 19 99. seemed as if all the artillery of heaven w were playing upon the earth,” said Farragut. That didn’t stop him. His sailors put out the fires and got the ships moving. What was laid across the Mississippi to keep the Yankee ships out?","choices":["a chain of cannon balls","a chain of old ships","planks of wood","tall mounds of mud"],"correct":1,"explanation":{"correct":"Answer: a chain of old ships. The passage explicitly states, 'In addition, a chain of hulks (old ships) was laid across the Mississippi to keep Yankee ships out.'","incorrect":[{"choice":"a chain of cannon balls","category":"misreading text details","reason":"While the forts were armed, the passage does not mention cannon balls being laid across the river. It specifically identifies 'hulks' or old ships."},"",{"choice":"planks of wood","category":"external information error","reason":"The passage identifies the barrier as 'hulks,' which are old ships, not planks of wood. Always look back at the text to verify the material described."},{"choice":"tall mounds of mud","category":"invented detail error","reason":"This detail is not present in the passage. The author describes a chain of ships, not geographical structures like mounds of mud."}]},"studyAid":{"definition":"To understand a text, look for specific nouns and descriptions that identify people, objects, or actions mentioned by the author.","example":"Text: 'The boy carried a heavy metal bucket.' Q: What did he carry? A: A heavy metal bucket.","strategyClue":"Scan the paragraph for the keyword 'Mississippi' and look for the sentence immediately following it that explains what was placed there to block the ships.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":22,"sourceCategory":"reading-test","sourceGrade":3,"sequence":124,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0129","version":3,"contentHash":"sha256:7f4f5a8f7bafbe69acf7fd40e50c412520ef58ff46a78c5b8ff66eec395577dc","question":"Read the following definitions. Ivy – a climbing vine with a woody stem and green leaves. Spruce – an evergreen tree with slender needles. Crocus – a spring blooming plant of the iris family with grass-like leaves and yellow, purple, or white flowers. Gladiolus – an iris -like plant with sword-like leaves and tall spikes of funnel- shaped flowers. Moss – a very small green plant that grows in velvety clusters on roc ks and moist ground. Which plants are most logically grouped together?","choices":["gladiolus, crocus","ivy, g ladiolus","spruce, moss","ivy, moss"],"correct":0,"explanation":{"correct":"Answer: gladiolus, crocus. These two plants are logically grouped because they are both flowering plants in the iris family, making them the most similar items on the list.","incorrect":["",{"choice":"ivy, g ladiolus","category":"mismatched plant types","reason":"An ivy is a woody climbing vine, while a gladiolus is a flowering plant with sword-like leaves. They have very different growth habits and structures."},{"choice":"spruce, moss","category":"incompatible classifications","reason":"A spruce is a large evergreen tree and moss is a tiny, non-flowering plant that grows in clusters. They do not share the same physical classification."},{"choice":"ivy, moss","category":"different botanical categories","reason":"Ivy and moss are fundamentally different; ivy is a climbing vine with woody stems, while moss is a small, non-vascular plant that lacks true stems or flowers."}]},"studyAid":{"definition":"Logical grouping, or categorization, involves identifying shared traits or characteristics that place items into the same class or family.","example":"Grouping a dog and cat as 'pets', or grouping a pen and pencil as 'writing tools'.","strategyClue":"Highlight the key descriptive words in each definition, such as 'plant', 'tree', or 'flower'. Look for the pair that shares the most specific descriptive labels provided in the text.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":27,"sourceCategory":"reading-test","sourceGrade":3,"sequence":129,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0130","version":3,"contentHash":"sha256:6a91401d31a77196a87918a7e8b6b05471df05ff19b143b1fae95b42e399ac00","question":"Look at the definitions. Dormitory – a room or building with many r ooms for sleeping and living in. Synagogue – a building or plac e for religious study. Igloo – a hut, usually dome-shaped and mad e from blocks of packed sno w. Apartment – a group of rooms to live in, especially one of a numb er in an apartment house. Campe r – a motor vehicle or trailwerequipped for ca mping out. Which defined places are most logically grouped to gether?","choices":["apartment, camper","synagogue, dormitory","igloo, camp er","dormitory, apartment"],"correct":3,"explanation":{"correct":"Answer: dormitory, apartment. These two terms are most logically grouped because they are both types of housing designed primarily for living and sleeping in.","incorrect":[{"choice":"apartment, camper","category":"mismatched housing type","reason":"While an apartment is a permanent living space, a camper is a portable vehicle. A dormitory and an apartment share a more specific connection as types of permanent residential buildings."},{"choice":"synagogue, dormitory","category":"functional mismatch","reason":"A synagogue is a place for religious study and worship, whereas a dormitory is a place for residential living. They do not share the same primary function."},{"choice":"igloo, camp er","category":"inconsistent category","reason":"An igloo is a traditional structure made of snow, while a camper is a modern motor vehicle. They belong to very different categories of shelter."},""]},"studyAid":{"definition":"To group words logically, look for a shared category or primary function, such as 'types of homes' or 'places for learning.'","example":"Group 'Chair, Sofa' (furniture) or 'Apple, Banana' (fruit). Avoid grouping 'Chair, Apple' because they belong to different categories.","strategyClue":"Identify the primary purpose for each noun in the list. Pick the two words that perform the exact same core function in our daily lives.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":28,"sourceCategory":"reading-test","sourceGrade":3,"sequence":130,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0133","version":3,"contentHash":"sha256:df991e36f9561b7d8f9d5b1e72bfeff7ba76fafac86c398d3ea9494f5c729bbb","question":"Read the passage. Stunned for only a moment, the youth invented a tale that only giants, the most gullible creatures on the earth, would believe. Unfortunately, it is a quirk of supernature, a paradox of the cruelest kind, that whatever giants believe becomes their truth. “What was your last job?” asked the boy, knowing full well that giants never do manual work and haven’t the intellect or dexterity required for other types of employment. From the context of this passage, which pair of words are opposites?","choices":["gullible, supernature","invented, tru","giants, paradox","cruelest, kind"],"correct":1,"explanation":{"correct":"Answer: invented, truth. To 'invent' a tale means to make something up that is not real, whereas 'truth' refers to something that is actually the case. These concepts represent opposites in the context of the passage.","incorrect":[{"choice":"gullible, supernature","category":"unrelated word meanings","reason":"Being 'gullible' refers to someone easily tricked, while 'supernature' refers to something beyond the natural world. These words are not opposites."},"",{"choice":"giants, paradox","category":"unrelated word meanings","reason":"A 'giant' is a creature and a 'paradox' is a confusing situation. They do not have an opposite relationship."},{"choice":"cruelest, kind","category":"incorrect pairing","reason":"While 'cruel' and 'kind' are opposites, the choice is 'cruelest' and 'kind'. Because they are different forms (a superlative and a base adjective), they are not direct opposites."}]},"studyAid":{"definition":"Antonyms are words that have opposite meanings. Finding opposites helps you understand how authors compare and contrast ideas in a story.","example":"hot vs. cold, fast vs. slow, light vs. dark","strategyClue":"Test each word pair by asking: 'If one word describes a state, does the other word describe the direct opposite state?' Look for pairs where both words are the same part of speech.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":31,"sourceCategory":"reading-test","sourceGrade":3,"sequence":133,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0140","version":3,"contentHash":"sha256:5ca2cc16406b84e228f62737b2e45cb5baf8205609fbe06a002d035cddf7bb05","question":"With the addition of a prefix, which word now means the opposite of do?","choices":["redo","doer","undo","doing"],"correct":2,"explanation":{"correct":"Answer: undo. Rule or clue: Reading comprehension means using details from the passage to understand ideas, events, and author choices. \"undo\" is the inference best supported by the clues in the text.","incorrect":[{"choice":"redo","reason":"\"redo\" is not the best inference because the text clues do not point to that idea."},{"choice":"doer","reason":"\"doer\" is not the best inference because the text clues do not point to that idea."},"",{"choice":"doing","reason":"\"doing\" is not the best inference because the text clues do not point to that idea."}]},"studyAid":{"definition":"Reading comprehension means using details from the passage to understand ideas, events, and author choices.","example":"Find the sentence or detail that supports the answer before choosing.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":38,"sourceCategory":"reading-test","sourceGrade":3,"sequence":140,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0142","version":3,"contentHash":"sha256:815a77a9488e33e68be7cc4c347a282e7e228463c961e101a589df09c5c46f27","question":"Read the announcement. Which selection gives you the most for your money?","choices":["1 slice of cake","4 cookies","2 brow nies","5 cookies"],"correct":3,"explanation":{"correct":"Answer: 5 cookies. To find the best value, compare the quantities provided in each option. Since 5 is the largest number in the list, 5 cookies provide the most items for the same cost.","incorrect":[{"choice":"1 slice of cake","category":"comparing small quantities","reason":"One slice is a single item. Five is a much larger amount than one, so this choice gives you less, not more."},{"choice":"4 cookies","category":"comparing similar items","reason":"While four cookies are a treat, five cookies are a larger quantity. Four is less than five, so this is not the most you can get."},{"choice":"2 brow nies","category":"comparing small quantities","reason":"Two brownies is a smaller amount than five cookies. Always identify the highest number when you are looking for the 'most'."},""]},"studyAid":{"definition":"When looking for the 'most' of something, compare the numbers to find the largest value.","example":"10 stickers are more than 3 stickers. 100 pages is more than 50 pages.","strategyClue":"Look at the numbers in front of each item. List them from smallest to largest and pick the one with the greatest value.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":40,"sourceCategory":"reading-test","sourceGrade":3,"sequence":142,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0143","version":3,"contentHash":"sha256:f9174c1988e8148c8d3407f309efd7f11e0b8f3bea135f861160d44e5742cf0f","question":"Read the passage. It was a cold and chilling night, and the cattle were restless. As the sun dropped behind the mountain range, the animals all started to come alive with anticipation. This was a night of the hunter and the hunted. The wolves were on the prowl for a meal, and the cattle knew they were being watched. Choose the word that is an antonym for restless.","choices":["fidgety","calm","tense","insomniac"],"correct":1,"explanation":{"correct":"Answer: calm. An antonym is a word that means the opposite. Since 'restless' describes animals that cannot stay still or are agitated, 'calm' is the best opposite because it describes a state of peace and stillness.","incorrect":[{"choice":"fidgety","category":"synonym error","reason":"Fidgety means moving around and being unable to sit still. This is a synonym of restless, not an antonym."},"",{"choice":"tense","category":"synonym error","reason":"Tense describes feeling nervous or wound up, which is very similar to how restless animals feel. This is a synonym, not an opposite."},{"choice":"insomniac","category":"unrelated meaning","reason":"An insomniac is someone who cannot sleep. While a restless animal might be awake, this word refers to a person's condition rather than the opposite of being restless."}]},"studyAid":{"definition":"Antonyms are words that have opposite meanings. Finding an antonym is like finding the 'flip side' of a word's definition.","example":"Hot/Cold, Happy/Sad, Fast/Slow","strategyClue":"Define the word in the passage first. Then, ask yourself, 'What is the exact opposite of that feeling or action?' Check if your choice describes the opposite state of being.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Expert-1_reading.pdf","sourceQuestionNumber":41,"sourceCategory":"reading-test","sourceGrade":3,"sequence":143,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0156","version":3,"contentHash":"sha256:531626ac607df7e2f55f165f5b46628a23da7c9d7f917ba4d75d8a4753515af7","question":"Read the story below. Robbie and h is best friend, John, like to solve mysteries. One day, they went to the library to get some books to read. In the library, the re was a marble statue of a lady. On her left hand, there was a large, beautiful diamon d ring. Everyone thought the r ing was cool. On their way back out of the library, they noticed the ring was missing. Which title best fits the story?","choices":["Polly’s Great Escape","The Case of the Missing Diamond Ring","A Trip to the Library","A Day with Jo hn and Rob bie"],"correct":1,"explanation":{"correct":"Answer: The Case of the Missing Diamond Ring. This title best fits the story because it focuses on the central mystery of the plot, which is the disappearance of the ring from the marble statue.","incorrect":[{"choice":"Polly’s Great Escape","category":"irrelevant plot point","reason":"This title mentions a character named Polly who is not in the story, and there is no escape mentioned in the plot."},"",{"choice":"A Trip to the Library","category":"vague story summary","reason":"While the story takes place in a library, this title is too general and does not mention the mystery, which is the most important part of the story."},{"choice":"A Day with Jo hn and Rob bie","category":"character focus only","reason":"This title only describes the characters, but it misses the main action of the story, which is solving the mystery of the missing ring."}]},"studyAid":{"definition":"A good story title should tell the reader what the main event or mystery of the story is about in a short and exciting way.","example":"A story about a lost puppy could be called 'The Search for Buddy'; a story about a baking disaster could be called 'The Great Cake Catastrophe.'","strategyClue":"Identify the biggest problem or the most exciting event in the story, then choose the title that highlights that specific event instead of just naming the characters or the setting.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":2,"sourceCategory":"reading-test","sourceGrade":3,"sequence":156,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0161","version":4,"contentHash":"sha256:c3a3f641380358ab22a2449fe08fc951dd5497b04b19999375f1aebe6d3a56da","question":"Read the list. Raccoo n Antelope Moose Deer Which of the following animals does not belong in the above group?","choices":["raccoon","deer","antelo pe","m oose"],"correct":0,"explanation":{"correct":"Answer: raccoon. The other animals listed—antelope, moose, and deer—are all members of the order Artiodactyla, commonly known as even-toed ungulates or hoofed animals. A raccoon is a procyonid and does not have hooves.","incorrect":["",{"choice":"deer","category":"Incorrect classification","reason":"Deer are part of the same group of hoofed animals as the others. They belong in this list because they are herbivores with hooves."},{"choice":"antelo pe","category":"Incorrect classification","reason":"Antelopes are hoofed mammals that fit perfectly with the other animals listed. They are not the odd one out."},{"choice":"m oose","category":"Incorrect classification","reason":"Moose are large, hoofed animals closely related to deer. They are a correct fit for the group provided."}]},"studyAid":{"definition":"To identify an item that does not belong, look for a shared trait or characteristic that three of the items have, but the fourth lacks.","example":"Group: Apple, Banana, Pear, Carrot (Carrot is the outlier because it is a vegetable, not a fruit). Group: Dog, Cat, Hamster, Shark (Shark is the outlier because it lives in water).","strategyClue":"List one main physical feature (like feet, diet, or habitat) for each animal. Find the one animal whose feature does not match the pattern of the others.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":7,"sourceCategory":"reading-test","sourceGrade":3,"sequence":161,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0165","version":3,"contentHash":"sha256:1ee30522fc0ab0159890ddf7eaa89c5b24648c5f2fd0e0f839cb77212c332839","question":"Read the passage. Everything was ready for the birthday party. The room was decorated with bright yellow balloons. The birthday cake was decorated like a giant soccer ball and was sitting in the middle of a round table. Which word is not an adjective?","choices":["bright","giant","party","round"],"correct":2,"explanation":{"correct":"Answer: party. In this sentence, 'party' acts as a noun because it is the thing that was being prepared. Adjectives describe nouns, while 'party' names the event itself.","incorrect":[{"choice":"bright","category":"descriptive adjective","reason":"The word 'bright' is an adjective because it describes what the yellow balloons look like. Adjectives often tell us about color or quality."},{"choice":"giant","category":"descriptive adjective","reason":"The word 'giant' is an adjective because it describes the size of the cake. It modifies the noun 'cake' to give us more information about it."},"",{"choice":"round","category":"descriptive adjective","reason":"The word 'round' is an adjective because it describes the shape of the table. It helps the reader visualize what the table looks like."}]},"studyAid":{"definition":"An adjective is a word that describes or modifies a noun or pronoun by telling us about its size, shape, color, or other qualities.","example":"The red car (red = adjective); The tiny mouse (tiny = adjective); The delicious snack (delicious = adjective).","strategyClue":"Try putting the word in the phrase 'the _____ thing.' If the word makes sense and describes that thing, it is likely an adjective. If the word names a thing, place, or person, it is a noun.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":11,"sourceCategory":"reading-test","sourceGrade":3,"sequence":165,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0167","version":3,"contentHash":"sha256:74859fb18fb9ce8bdee9ddd847202216336d614a94a5eab23f63c4e81a760587","question":"Read the following birthd ay announcements: 1. Wednesday – Birthday Par ty – 600 pm 2. Wednesday: Birthday Party: 6,00 p.m. 3. Wednesday, Birthday Party, 6:00 p.m. 4. Wednesday, Birthday, Party, 6:00 p.m. Which announcement is written in the correct format?","choices":["1","2","3","4"],"correct":2,"explanation":{"correct":"Answer: 3. This option uses the standard format for announcements: a comma separates the day from the event, and a colon is used to correctly indicate time (6:00 p.m.).","incorrect":[{"choice":"1","category":"incorrect punctuation marks","reason":"The dash after 'Wednesday' is informal, and '600 pm' lacks the necessary colon and periods to properly show it is a time."},{"choice":"2","category":"excessive colon usage","reason":"While colons can introduce information, using three colons in one line is confusing and grammatically non-standard for an announcement."},"",{"choice":"4","category":"unnecessary comma usage","reason":"Placing commas between 'Birthday' and 'Party' breaks up the name of the event, making it read as two separate things instead of one single event."}]},"studyAid":{"definition":"Use commas to separate parts of an announcement and colons specifically to separate the hour from the minutes in a time.","example":"Monday, Soccer Practice, 4:00 p.m.; Friday, Movie Night, 7:30 p.m.","strategyClue":"Check if your chosen format treats the date, the event name, and the time as three distinct blocks, using standard separators for each.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":13,"sourceCategory":"reading-test","sourceGrade":3,"sequence":167,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0173","version":3,"contentHash":"sha256:dd3e34fda947da386aa820bd2d6003ba18335a96f9e2d3136d214c47b5c00e61","question":"Look at the list for Group C below: Which category title best fits the list of words in Group C?","choices":["writing devices","furniture pieces","communication devices","music devices"],"correct":2,"explanation":{"correct":"Answer: communication devices. All the words in this group—such as phone, letter, or radio—are tools used to send messages or share information between people.","incorrect":[{"choice":"writing devices","category":"too narrow scope","reason":"While some items might be used for writing, this title misses other items in the group that are for speaking or listening, making it an incomplete description."},{"choice":"furniture pieces","category":"incorrect classification","reason":"Furniture is meant for sitting or storage, whereas items in this group are used for sharing messages. These categories describe completely different types of objects."},"",{"choice":"music devices","category":"misidentified function","reason":"Although some communication tools can play music, the primary purpose of the items in this list is to exchange information, not to produce artistic sound."}]},"studyAid":{"definition":"A category is a group of things that share common features or purposes. To find the best title, identify the one thing every item in the list has in common.","example":"List: {car, bus, train} -> Title: Vehicles; List: {rose, tulip, daisy} -> Title: Flowers","strategyClue":"Look at each item in the list and ask yourself: 'What is this object used for?' Then, find the title that covers the main purpose shared by all those items.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":19,"sourceCategory":"reading-test","sourceGrade":3,"sequence":173,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0175","version":3,"contentHash":"sha256:dad6fd7ab83c7fab221a93a1f6dc56c369df5f4e4e0a91fe6935ea58655327d2","question":"Read the story. John and his mom were shopping for a new set of rollerblades. As they looked at several pairs, John said, “Hey, Mom, look at these!” His mother replied by saying, “Oh, those are too much, how about these?” John shrugged and held up another pair. “This pair is on sale,” he said as he walked over to show her. The words “these,” “those,” and “this” refer to:","choices":["wheels","shoes","knee pads","rollerblades"],"correct":3,"explanation":{"correct":"Answer: rollerblades. The words 'these,' 'those,' and 'this' are demonstrative pronouns used here to point to the specific items John and his mother are shopping for, which are the rollerblades.","incorrect":[{"choice":"wheels","category":"incorrect noun reference","reason":"While rollerblades have wheels, John is holding up and showing his mother entire pairs of rollerblades, not just the individual parts."},{"choice":"shoes","category":"incorrect noun reference","reason":"The story explicitly states they are shopping for rollerblades, not shoes. Pronouns must refer to the object mentioned in the text."},{"choice":"knee pads","category":"incorrect noun reference","reason":"Knee pads are not mentioned in the story. These words are used to point to the rollerblades John is holding."},""]},"studyAid":{"definition":"Pronouns are words that replace nouns. Words like 'this', 'that', 'these', and 'those' are used to point out specific objects.","example":"I want that book (the book near you). These cookies (the cookies I am holding) are delicious.","strategyClue":"Look at the sentence immediately before the pronouns were used and identify the main object being discussed by the characters.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":21,"sourceCategory":"reading-test","sourceGrade":3,"sequence":175,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0177","version":5,"contentHash":"sha256:ab28d1aa7b4e947f10b069a66065c5adc2de89b887ccefaec4cb7da6d75a320a","question":"Identify two words that are synonyms in the following paragr aph. On Saturday, we went to the racetrack to see the horses. When the race began, the horses started to gallop. By the end of the race, the y were making a dash for the finish line.","choices":["gallop/dash","horses/race","finish/started","line/racetrack"],"correct":0,"explanation":{"correct":"Answer: gallop/dash. Both of these words mean to move quickly or run, making them synonyms in the context of the horses' movement.","incorrect":["",{"choice":"horses/race","category":"unrelated noun categories","reason":"A horse is an animal and a race is an event. These words represent very different things and do not share the same meaning."},{"choice":"finish/started","category":"antonyms (opposites)","reason":"These words are actually opposites. To start is to begin, while to finish is to end; they mean the opposite of each other."},{"choice":"line/racetrack","category":"unrelated nouns","reason":"A line is a mark or a row, and a racetrack is a place. These words describe different concepts and do not mean the same thing."}]},"studyAid":{"definition":"Synonyms are two or more words that have the same or very similar meanings.","example":"happy/glad, big/large, fast/quick","strategyClue":"Look for words that describe the same action or object. Try replacing one word with the other in the sentence to see if the meaning stays the same.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":23,"sourceCategory":"reading-test","sourceGrade":3,"sequence":177,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0181","version":3,"contentHash":"sha256:e1a1ed3223cf9a67916a5cdae8503f5b1c80582e81ac983abd41b12f5a12a50b","question":"Read the following sentences. As we were walking through the forest we saw many beautiful wildflowers. We decided to pick some of them to take home so our p leasure would continue. What is the meaning of pleasure?","choices":["frustration","depression","blo ssom","enjoyment"],"correct":3,"explanation":{"correct":"Answer: enjoyment. The word 'pleasure' refers to a feeling of happy satisfaction or delight, which is synonymous with 'enjoyment' in this context.","incorrect":[{"choice":"frustration","category":"antonym error","reason":"Frustration is the opposite of pleasure. While picking flowers brings happiness, it does not cause feelings of annoyance or being unable to change a situation."},{"choice":"depression","category":"unrelated emotion","reason":"Depression is a state of deep sadness. Because the characters chose to pick flowers to continue their experience, they are feeling happiness, not sadness."},{"choice":"blo ssom","category":"confusing related terms","reason":"A blossom is a flower, which is an object in the sentence, but it is not an emotion or a state of being like 'pleasure'."},""]},"studyAid":{"definition":"A synonym is a word that has the same or nearly the same meaning as another word.","example":"happy/joyful, large/big, fast/quick","strategyClue":"Replace the target word in the sentence with each of the choices. Ask yourself which word makes the sentence describe a positive feeling that matches the characters' actions.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":27,"sourceCategory":"reading-test","sourceGrade":3,"sequence":181,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0182","version":3,"contentHash":"sha256:f348433e4b74823751da808f9a6c61caa8184fe93dbf655b41042c9643e724f7","question":"Which is NOT an element of a legend?","choices":["A ver y old story h anded down through generations.","Astory that may have a historical basis.","Ashort story that teaches a moral lesson.","Astory that emphasizes traits admired by a culture."],"correct":2,"explanation":{"correct":"Answer: A short story that teaches a moral lesson. This description actually defines a fable, which is different from a legend. Legends are stories that focus on historical figures or heroic deeds, while fables are specifically designed to teach a moral lesson.","incorrect":[{"choice":"A ver y old story h anded down through generations.","reason":"\"A ver y old story h anded down through generations.\" is not the best inference because the text clues do not point to that idea."},{"choice":"Astory that may have a historical basis.","reason":"\"Astory that may have a historical basis.\" is not the best inference because the text clues do not point to that idea."},"",{"choice":"Astory that emphasizes traits admired by a culture.","reason":"\"Astory that emphasizes traits admired by a culture.\" is not the best inference because the text clues do not point to that idea."}]},"studyAid":{"definition":"A legend is a traditional story that is often based on history and features heroic characters, whereas a fable is a short tale used to teach a specific moral lesson.","example":"Legend: King Arthur pulling the sword from the stone; Fable: The Tortoise and the Hare.","strategyClue":"Look at the purpose of each choice; ask yourself if the story is intended to teach a lesson to the reader or if it is describing a person or event from the past.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":28,"sourceCategory":"reading-test","sourceGrade":3,"sequence":182,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0185","version":3,"contentHash":"sha256:89e8227c2e1fbd5f246ebc0702ae0ac8b2ce113f4d265b051755ca17d32db16f","question":"Which word ends with the same sound as tough?","choices":["though","cuff","fought","tru"],"correct":1,"explanation":{"correct":"Answer: cuff. The word 'tough' ends with the /f/ sound. 'Cuff' also ends with the /f/ sound, making them a match in pronunciation.","incorrect":[{"choice":"though","category":"vowel-consonant mismatch","reason":"The word 'though' ends with a silent 'gh' and a long 'o' sound, which is very different from the /f/ sound at the end of 'tough'."},"",{"choice":"fought","category":"final consonant mismatch","reason":"The word 'fought' ends with a 't' sound, not the 'f' sound heard at the end of 'tough'. Pay close attention to the very last sound you make."},{"choice":"tru","category":"vowel sound ending","reason":"The word 'tru' (a common misspelling of true) ends with a vowel sound. 'Tough' requires a consonant sound, specifically the /f/ sound, at the end."}]},"studyAid":{"definition":"Words can have the same ending sound even if they are spelled with different letters.","example":"cough / off, tough / rough, phone / leaf (end with same sound)","strategyClue":"Say each word out loud slowly and focus only on the very last sound your mouth makes before you stop talking.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":31,"sourceCategory":"reading-test","sourceGrade":3,"sequence":185,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0192","version":3,"contentHash":"sha256:7c0e728d3f77217ac3b578f7e0e03a5cb4947bca34d8b4ce455476e9924adaa7","question":"With the addition of a prefix, which word now means the opposite of do?","choices":["redo","doer","undo","doing"],"correct":2,"explanation":{"correct":"Answer: undo. The prefix 'un-' is added to the beginning of a word to mean the opposite of the original word.","incorrect":[{"choice":"redo","category":"prefix meaning confusion","reason":"The prefix 're-' means to do something again, not the opposite. 'Redo' means to do it once more, rather than canceling the action."},{"choice":"doer","category":"suffix vs prefix","reason":"Adding '-er' to the end makes the word a noun referring to the person who performs the action, not the opposite of the action."},"",{"choice":"doing","category":"suffix vs prefix","reason":"Adding '-ing' to the end indicates that an action is currently happening, not that it is being reversed or undone."}]},"studyAid":{"definition":"A prefix is a group of letters added to the beginning of a word to change its meaning, such as 'un-' meaning 'not' or 'to reverse'.","example":"happy -> unhappy (opposite), tie -> untie (reverse), lock -> unlock (reverse)","strategyClue":"Think about whether you are trying to change the word to mean 'again' (repeat) or 'opposite' (reverse) before choosing your prefix.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":38,"sourceCategory":"reading-test","sourceGrade":3,"sequence":192,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0196","version":3,"contentHash":"sha256:da39f7c8fbd7d5b2a054be67b3188c72322c655293afdcf13fcbb28da1cab37e","question":"Given the word base, which of the following would be an appropriate compound word?","choices":["baseball","baseless","abase","bases"],"correct":0,"explanation":{"correct":"Answer: baseball. A compound word is formed when two smaller, independent words are joined together to create a new word with a new meaning. Both 'base' and 'ball' are standalone words that combine to make 'baseball'.","incorrect":["",{"choice":"baseless","category":"base plus suffix","reason":"The word 'less' is a suffix, not a free-standing noun or verb that creates a compound word. This is an example of a base word plus an ending, not two words combined."},{"choice":"abase","category":"prefix plus base","reason":"'A' is not a separate word in this context; it acts as a prefix added to the beginning of 'base'. Compound words require two complete words joined together."},{"choice":"bases","category":"plural noun","reason":"'Bases' is just the plural form of the word 'base' made by adding a suffix. It does not contain a second distinct word."}]},"studyAid":{"definition":"A compound word is formed when two complete words are joined together to create a brand-new word with its own unique meaning.","example":"sun + flower = sunflower; pan + cake = pancake; rain + bow = rainbow","strategyClue":"Look at each option and try to split it into two separate, real words. If you can identify two distinct words that each have their own meaning, you have found a compound word.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":42,"sourceCategory":"reading-test","sourceGrade":3,"sequence":196,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0054","version":3,"contentHash":"sha256:3dca391f3b19e80edd35e5b0b921c52481fab90959960cdd8a9a301d69115559","question":"Read the list and answer the question. Things to do on Tuesday: 1. Go to the library 2. Buy carrots at the market 3. Call the telephone company 4. Wrap Shelly’s birthday present. What do you think Maria will do with her list?","choices":["t ake it to school","color it purple","use it to check each thing off as she completes it","use it to fold and decorate a birthday card"],"correct":2,"explanation":{"correct":"Answer: use it to check each thing off as she completes it. A to-do list is a tool meant to help people keep track of their tasks throughout the day.","incorrect":[{"choice":"t ake it to school","category":"irrelevant task","reason":"There is no information in the list about school. The items on the list are errands and chores, not school supplies."},{"choice":"color it purple","category":"unrelated activity","reason":"The list is designed for organizing tasks, not for art projects. Coloring it would not help Maria manage her schedule."},"",{"choice":"use it to fold and decorate a birthday card","category":"wrong purpose","reason":"While there is a mention of a birthday present, the list is a checklist of actions, not a material for crafting a card."}]},"studyAid":{"definition":"A to-do list is a list of tasks that someone needs to complete. Its main purpose is to help people remember what they need to do.","example":"Grocery lists help shoppers remember items, and chore charts help students remember their responsibilities.","strategyClue":"Look at the items provided and ask yourself: what is the most logical way a person interacts with a list of tasks once they have started working?","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Basic-2_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":54,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0158","version":3,"contentHash":"sha256:e5399a5e1d2fe24493220caec80566b40ac69f5ea1669bf5d42a435655804afa","question":"If Jacob wanted to read a book about animals, which title would he probably choose?","choices":["The Dolphin Story","Singing a Song","Through the Tunnel","Lost in Caves"],"correct":0,"explanation":{"correct":"Answer: The Dolphin Story. The question specifically asks for a book about 'animals', and a dolphin is an animal, making this the only title that matches the topic.","incorrect":["",{"choice":"Singing a Song","category":"irrelevant topic","reason":"While someone might sing a song, this title focuses on music or performance, not the animal kingdom."},{"choice":"Through the Tunnel","category":"irrelevant topic","reason":"This title suggests a journey or a setting, but it does not mention or imply the study of animals."},{"choice":"Lost in Caves","category":"irrelevant topic","reason":"A cave is a place where animals might live, but the title itself refers to an adventure or location, not specifically an animal-themed book."}]},"studyAid":{"definition":"To find the correct answer in a reading comprehension task, look for keywords in the prompt and match them with information provided in the options.","example":"Prompt: Find the fruit. Choices: 'Carrot', 'Apple', 'Milk'. Correct: 'Apple'.","strategyClue":"Underline the key topic mentioned in the question prompt. Then, read each choice and ask yourself: 'Does this directly relate to that specific topic?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-2_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":158,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0248","version":3,"contentHash":"sha256:bc19d5c3afa2b458affff0c85c78aa7ed0460220175292e4f272e7a2700f9512","question":"Read the passage. Scientists are still not able to predict ear thquakes, but they are co ntinuing to discover various indicators of possible earthquakes. Scientist using a Richter Scale, which gives a numerical indication of the severity of the earthquake, typically measure earthquakes. This passage is most likely from a:","choices":["jo urnal","novel","play","essay"],"correct":3,"explanation":{"correct":"Answer: essay. An essay provides factual information and explains scientific concepts or research findings, such as earthquake measurement, in an informative and objective tone.","incorrect":[{"choice":"jo urnal","category":"technical format mismatch","reason":"While this passage discusses science, a 'journal' usually refers to a personal diary of thoughts and daily experiences, rather than an objective explanation of natural phenomena."},{"choice":"novel","category":"fictional narrative style","reason":"A novel is a work of fiction meant to tell a story with characters and plot. The provided text is purely informational and lacks the narrative elements found in fiction."},{"choice":"play","category":"script structure mismatch","reason":"A play is written in the form of a script with character dialogue and stage directions. This text is written as descriptive paragraphs, not as a performance piece."},""]},"studyAid":{"definition":"Text types are defined by their purpose: an essay informs or argues, a novel entertains through story, a play uses dialogue for performance, and a journal records personal reflections.","example":"Essays include research articles or reports. Novels include mystery or fantasy books. Plays include scripts with character names followed by lines.","strategyClue":"Look at the tone of the writing. If it explains facts, scientific processes, or ideas without characters or dialogue, categorize it by its informative purpose.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Advanced-2_Literature.pdf","sourceQuestionNumber":8,"sourceCategory":"literature","sourceGrade":3,"sequence":248,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0264","version":3,"contentHash":"sha256:1a7a6610c670805d3afc06e51687b56fdebeee7656549c524499fd3dc3568cc0","question":"Read the story. Kate woke in the middle of the night. She was shaking. She ran to her parents’ room crying. They hugged her, told her she was okay and tucked her back in bed. From the story, you can tell _________________.","choices":["Kate is late for school.","Kate likes to play jokes.","Kate had a bad dream.","Kate had a fight with her sister."],"correct":2,"explanation":{"correct":"Answer: Kate had a bad dream. The context clues—waking up in the middle of the night, shaking, and crying—are classic indicators that a character has experienced a nightmare.","incorrect":[{"choice":"Kate is late for school.","category":"logic error","reason":"The story takes place in the middle of the night, not in the morning. Being late for school usually happens when waking up after the sun is already up."},{"choice":"Kate likes to play jokes.","category":"unsupported inference","reason":"There is no evidence in the text suggesting Kate is joking; her reaction of crying and shaking shows genuine fear or distress."},"",{"choice":"Kate had a fight with her sister.","category":"unsupported inference","reason":"The text does not mention a sister at all. Relying on outside details not present in the paragraph leads to an incorrect inference."}]},"studyAid":{"definition":"Making an inference means using clues from the text plus what you already know to figure out something the author did not say directly.","example":"If a character is wearing a raincoat and carrying an umbrella, you can infer it is raining outside.","strategyClue":"Look at the character's physical actions (shaking, crying) and the time of day, then ask yourself, 'What event usually causes someone to feel this way at this time?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":4,"sourceCategory":"literature","sourceGrade":3,"sequence":264,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0266","version":3,"contentHash":"sha256:80db4dd3f5f24673d556c9928db628a70ad6315f98332b76eb8621ac2e757b81","question":"Read the story. Sue and Al went everywhere together. They went to the park to play. They went swimming at the pool. They ate lunch together and even had dinner at each other’s house. We can tell that Sue and Al were ___________________.","choices":["school buddies","not friends","brother and sister","best friends"],"correct":3,"explanation":{"correct":"Answer: best friends. The story shows that Sue and Al spend all their time together, including eating meals and playing, which is how we describe close companions.","incorrect":[{"choice":"school buddies","category":"too specific","reason":"While they might be school buddies, the story mentions they spend time together at home during lunch and dinner, which suggests a closer bond than just school."},{"choice":"not friends","category":"opposite meaning","reason":"This choice contradicts the story. People who do everything together and share meals are definitely friends."},{"choice":"brother and sister","category":"unsupported assumption","reason":"The story does not mention a family relationship. 'Best friends' is the best fit because it describes their actions rather than guessing their family tree."},""]},"studyAid":{"definition":"Drawing a conclusion means using clues from the text to make a logical guess about something that isn't directly stated.","example":"If a character is wearing a raincoat and carrying an umbrella, you can conclude it is raining outside.","strategyClue":"Look at the actions described in the story. Ask yourself, 'What kind of relationship typically involves people doing all these things together?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":6,"sourceCategory":"literature","sourceGrade":3,"sequence":266,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0270","version":3,"contentHash":"sha256:3eb9216a3e6eccd89704f2bbf6a0e833685394e43a0e86e5595aaca4dd3c56ed","question":"Read the passage. The zoo is a very exciting place to visit. You can see lots of amazing animals. You can learn interesting facts about them. You will never be bored at the zoo. From this passage, you can tell that:","choices":["Amazing animals live in the zoo.","The zoo is a boring place to go.","The zoo is a great place to visit.","Zoo animals are fun."],"correct":2,"explanation":{"correct":"Answer: The zoo is a great place to visit. This is the correct choice because the passage explicitly uses the phrase 'very exciting place to visit,' which directly supports the idea that it is a great place to go.","incorrect":[{"choice":"Amazing animals live in the zoo.","category":"not the main point","reason":"While the passage mentions that you can see amazing animals, this is a supporting detail rather than the overall conclusion about the experience of visiting the zoo."},{"choice":"The zoo is a boring place to go.","category":"opposite of text","reason":"The text explicitly states 'You will never be bored at the zoo,' so saying it is a boring place directly contradicts the passage."},"",{"choice":"Zoo animals are fun.","category":"inferred opinion","reason":"Although this might be true, the passage focuses on the experience of the visitor rather than the personality of the animals themselves."}]},"studyAid":{"definition":"An author's main point or 'big idea' summarizes the overall message, while supporting details are smaller facts that help prove that main point.","example":"Main Point: 'My dog is very smart.' Supporting Detail: 'He can sit, stay, and roll over on command.'","strategyClue":"Look for the sentence that summarizes the writer's main feeling or opinion about the topic rather than just picking a single fact mentioned in the paragraph.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":10,"sourceCategory":"literature","sourceGrade":3,"sequence":270,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-inference-q0288","version":3,"contentHash":"sha256:2c08737303c527087548062bfd4b3c39c7b800571f9deb758c678bd695f5f5bb","question":"Read the passage. Now, all the Crocketts were big, but Davy was big even for a Crockett. He weighed two hundred pounds, fourteen ounces, and he was as frisky as a wildcat. His ma and his Aunt Ketinah stood over Davy, trying to get him to sleep. “Davy is Born”. Elements of Literature: Second Course. Holt, Rinehart, Winston 1997. Which was NOT true of Davy Crockett?","choices":["He was a big man.","He was a city boy.","He was as frisky as a wild cat.","He weighed 200 pounds and 14 ounces."],"correct":1,"explanation":{"correct":"Answer: He was a city boy. The passage explicitly describes Davy as a Crockett and mentions his mother and aunt caring for him in a setting that implies a rural or frontier upbringing, with no mention of city life.","incorrect":[{"choice":"He was a big man.","category":"Inaccurate comprehension error","reason":"This is actually true! The text says, 'all the Crocketts were big, but Davy was big even for a Crockett,' so we cannot select this as the statement that is 'NOT' true."},"",{"choice":"He was as frisky as a wild cat.","category":"Inaccurate comprehension error","reason":"This statement is true according to the passage. The author uses the simile 'as frisky as a wildcat' to describe his energetic nature."},{"choice":"He weighed 200 pounds and 14 ounces.","category":"Inaccurate comprehension error","reason":"The text confirms this detail by stating, 'He weighed two hundred pounds, fourteen ounces,' making this a true statement rather than the correct answer."}]},"studyAid":{"definition":"Reading comprehension requires finding specific facts directly stated in the text to confirm if a statement is true or false.","example":"If a text says 'The dog is brown,' a statement saying 'The dog is blue' is false.","strategyClue":"Scan the text for each specific choice and put a checkmark next to the ones you can find evidence for. The choice that does not have evidence in the text is your correct answer.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-inference","sourceFile":"Proficient-2_Literature.pdf","sourceQuestionNumber":8,"sourceCategory":"literature","sourceGrade":3,"sequence":288,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
